script:
// "Check Pilot" toolbar button for xticket.
//
// Front end only: call the app method, render what comes back. It makes no
// request to Pilot -- it does not know Pilot's URL and holds no credentials --
// and it contains no business logic. There is no Server Script in the chain:
//
//     this script  ->  app_apis.connector.get_snapshot  ->  Pilot
//
// Layout is deliberately two-tier. A technician standing at the vehicle needs
// to answer "is this thing installed and working?" in a few seconds, so the
// first screen is a pass/fail checklist plus the map. Everything else -- the
// full field dump, diagnostics and raw payload -- sits behind "Show all".
//
// The map uses the Leaflet build frappe already bundles in libs.bundle.js, and
// the tile servers frappe itself configures in frappe.utils.map_defaults, so it
// adds no new dependency and no new external host beyond what the desk's own
// Geolocation control already contacts.
//
// Installed as a Client Script record (dt=xticket, view=Form) so it is editable
// from the desk at /app/client-script.

frappe.ui.form.on("xticket", {
	refresh(frm) {
		if (frm.is_new()) return;

		// One "Check" dropdown, not three standalone buttons -- this item is
		// added by THIS script; "xticket-check-pilot2" and "xticket-check-im"
		// each add their own item to the SAME group ("Check"), which is a
		// property of the toolbar at runtime, not of any one script. Frappe
		// merges same-named groups regardless of which Client Script called
		// add_custom_button, so all three land under one button correctly
		// however many of these scripts happen to be enabled.
		frm.add_custom_button(__("Pilot (WSL)"), () => pilot_check(frm), __("Check"));
	},
});

// Titles the app raises when the lookup simply found nothing. Kept as an
// explicit list rather than a keyword match: an account rejected with 401 also
// returns no vehicle, and calling a bad credential "not found" sends a
// technician hunting for a device when the login is what is broken.
const PILOT_NOT_FOUND_TITLES = ["Pilot: No Data", "No IMEI", "No Pilot Account"];

// The app's frappe.throw arrives as `_server_messages`: a JSON string holding an
// array of JSON strings, each {title, message, indicator}.
function pilot_server_messages(r) {
	try {
		return JSON.parse(r._server_messages || "[]").map((m) => {
			try {
				return JSON.parse(m);
			} catch (e) {
				return { message: String(m) };
			}
		});
	} catch (e) {
		return [];
	}
}

// Pull the IMEI back out of the failure text so the "Use Admin" fallback
// button knows what to ask the admin sweep for. connector.py's failure-detail
// message is always built as "...for IMEI {imei} on node {node}.", so this is
// a stable contract with the server, not a guess.
function pilot_extract_imei(text) {
	const m = /\bIMEI\s+(\d{6,20})\b/i.exec(text || "");
	return m ? m[1] : null;
}

// Manual, explicit fallback -- never automatic. Re-sweeps the whole estate via
// the admin account (slow: no single-device query exists on that side) and
// renders the result through the SAME dialog as a normal customer-login read.
function pilot_admin_fallback(frm, imei) {
	frappe.call({
		method: "app_apis.pilot_admin.get_vehicle_live_admin",
		args: { imei },
		freeze: true,
		freeze_message: __("Sweeping the full Pilot estate via the admin account (30–90s)…"),
		callback(r) {
			if (!r || !r.message) {
				frappe.msgprint({
					title: __("Pilot"),
					message: __("The admin sweep returned an empty response."),
					indicator: "orange",
				});
				return;
			}
			pilot_show(frm, r.message);
		},
	});
}

// Restate an empty result as a plain "not found" notice.
//
// This is registered as an `error_handlers` entry rather than an `error` or
// `always` callback, and that is the whole trick: frappe only draws its own
// dialog when NO handler is registered for the exception type --
//
//     if (handlers.length === 0) { frappe.hide_msgprint(); frappe.msgprint(messages); }
//         -- frappe/public/js/frappe/request.js
//
// so registering one replaces frappe's dialog outright instead of racing it.
// The consequence is that this function now owns EVERY ValidationError from the
// call: any branch that does not print something swallows the message, which is
// why the last branch re-renders exactly what frappe would have shown.
// `frm` is bound in by pilot_check below (`error_handlers` only ever passes
// frappe the response object), so the "Use Admin" button knows which form to
// render into.
// A ticket names its device in whichever field the job was created through, so
// the first value that looks like a device serial wins. Used only as a fallback
// for the admin sweep, so a wrong guess costs a slow lookup, never a wrong read.
function pilot_ticket_imei(frm) {
	const d = (frm && frm.doc) || {};
	const candidates = [
		d.device_serial_new, d.device_serial, d.device_id_link, d.device_id_scan, d.serial,
	];
	for (const c of candidates) {
		const m = /\b(\d{10,20})\b/.exec(String(c || ""));
		if (m) return m[1];
	}
	return null;
}

function pilot_error_handler(r, frm) {
	const msgs = pilot_server_messages(r);
	const title = (msgs[0] && msgs[0].title) || "";
	const body = msgs.map((m) => m.message || "").join("\n\n");

	// Folded away, not dropped: the raw server text is what made these dialogs
	// too long to read, but it is still the only thing that explains an
	// unexpected failure. Closed by default, so the dialog is one line.
	const detail = body
		? `<details style="margin-top:8px"><summary style="cursor:pointer;font-size:11px;
				color:var(--text-muted)">${__("Details")}</summary>
				<div style="margin-top:6px;font-size:11px;color:var(--text-muted);
					white-space:pre-wrap">${frappe.utils.escape_html(body)}</div></details>`
		: "";

	// Credentials are tested FIRST, on the body rather than the title. A run in
	// which every account was rejected with 401 still comes back titled
	// "Pilot: No Data", so matching the title alone would report a rejected
	// login as a missing device -- sending a technician to hunt for hardware
	// when the account is what is broken.
	if (/\b401\b|unauthor|credential|rejected/i.test(body + title)) {
		// Fall back to the ticket's own device serial when the failure text
		// carries no IMEI, so the admin sweep is offered on EVERY rejected
		// login -- not only the ones that happened to name the device.
		const imei = pilot_extract_imei(body + title) || pilot_ticket_imei(frm);
		frappe.msgprint({
			title: __("Pilot Login Rejected"),
			indicator: "red",
			message:
				`<div style="font-size:13px"><b>${__(
					"Login rejected by Pilot \u2014 not a missing device."
				)}</b></div>` + detail,
			// Manual fallback only -- never automatic (a wrong customer login
			// should not silently trigger a 30-90s whole-estate admin sweep on
			// every check). Hidden only when neither the failure text nor the
			// ticket names a device, because then there is nothing to sweep for.
			primary_action: imei
				? {
						label: __("Use Admin (slow — 30–90s)"),
						action: () => pilot_admin_fallback(frm, imei),
				  }
				: null,
		});
		return;
	}

	// Reached the platform, it simply holds nothing for this device. Red, not
	// orange: a device the platform cannot see is a fault to act on, and it is
	// the answer the technician opened this dialog for.
	if (PILOT_NOT_FOUND_TITLES.some((t) => title.indexOf(t) !== -1)) {
		frappe.msgprint({
			title: __("No Data"),
			indicator: "red",
			message:
				`<div style="font-size:14px;color:var(--red-600,#c0392b)"><b>${__(
					"No data"
				)}</b></div>
				<div style="margin-top:4px;font-size:12px;color:var(--text-muted)">${__(
					"Reached Pilot; it holds nothing for this device."
				)}</div>` + detail,
		});
		return;
	}

	// Not ours to interpret -- render exactly what frappe would have, so
	// registering this handler can never silently swallow a message.
	if (msgs.length) {
		msgs.forEach((m) => frappe.msgprint(m));
	} else {
		frappe.msgprint({
			title: __("Pilot"),
			indicator: "red",
			message: __("The request failed and Pilot returned no message."),
		});
	}
}

function pilot_check(frm) {
	frappe.call({
		method: "app_apis.connector.get_snapshot",
		args: { ticket: frm.doc.name },
		freeze: true,
		freeze_message: __("Contacting Pilot…"),
		error_handlers: { ValidationError: (r) => pilot_error_handler(r, frm) },
		callback(r) {
			if (!r || !r.message) {
				frappe.msgprint({
					title: __("Pilot"),
					message: __("Pilot returned an empty response."),
					indicator: "orange",
				});
				return;
			}
			pilot_show(frm, r.message);
		},
	});
}

// ---------------------------------------------------------------- helpers

// Pilot HTML-encodes some strings ("Queen's Taste Bakery &amp; Sweets").
// Decode first, then escape for output -- decoding alone would be an XSS hole,
// escaping alone would show the reader a literal "&amp;".
function pilot_decode(s) {
	const el = document.createElement("textarea");
	el.innerHTML = String(s);
	return el.value;
}

function pilot_esc(v) {
	return frappe.utils.escape_html(pilot_decode(v));
}

function pilot_dash(v) {
	return v === null || v === undefined || v === "" ? "&mdash;" : pilot_esc(v);
}

// Seconds -> "2h 5m" / "5m 12s" / "12s". Pilot reports `moving` and `parking`
// as counters in the current state, not as booleans.
function pilot_duration(sec) {
	sec = Math.max(0, Math.floor(Number(sec) || 0));
	if (!sec) return "0s";
	const h = Math.floor(sec / 3600);
	const m = Math.floor((sec % 3600) / 60);
	const s = sec % 60;
	if (h) return `${h}h ${m}m`;
	if (m) return `${m}m ${s}s`;
	return `${s}s`;
}

function pilot_ago(sec) {
	if (sec === null || sec === undefined) return __("unknown");
	sec = Math.max(0, Math.floor(sec));
	if (sec < 60) return __("{0}s ago", [sec]);
	if (sec < 3600) return __("{0}m ago", [Math.floor(sec / 60)]);
	if (sec < 86400) return __("{0}h ago", [Math.floor(sec / 3600)]);
	return __("{0}d ago", [Math.floor(sec / 86400)]);
}

function pilot_epoch_text(epoch) {
	if (!epoch) return "";
	// frappe renders in the user's configured timezone, which is what the
	// reader expects to see -- not the raw UTC of the epoch.
	return frappe.datetime.str_to_user(
		frappe.datetime.convert_to_user_tz(
			moment.unix(Number(epoch)).utc().format("YYYY-MM-DD HH:mm:ss")
		)
	);
}

// 344 -> "NNW". Pilot sends heading in degrees on this account, but sends a
// literal string ("NE") on others, so pass non-numeric values straight through.
function pilot_compass(dir) {
	const n = Number(dir);
	if (dir === null || dir === undefined || dir === "" || Number.isNaN(n)) {
		return dir ? String(dir) : null;
	}
	const pts = ["N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE",
		"S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW"];
	return pts[Math.round((n % 360) / 22.5) % 16];
}

// Every sensor Pilot reported, probes included, as one flat list.
function pilot_all_sensors(d) {
	const all = (d.others || []).slice();
	(d.probes || []).forEach((p) => {
		if (p.temperature) all.push(p.temperature);
		if (p.humidity) all.push(p.humidity);
	});
	return all;
}

function pilot_find_sensor(d, re) {
	return pilot_all_sensors(d).find((s) => re.test(String(s.name || "")));
}

// ---------------------------------------------------------------- render

function pilot_show(frm, d) {
	const esc = pilot_esc;
	const dash = pilot_dash;

	const st = d.state || {};
	const loc = d.location || {};
	const dev = d.device || {};
	const info = d.ticket_info || {};
	const diag = d.diagnostics || {};
	const lu = d.last_update || {};

	// Prefer the server's figures: it compares Pilot's timestamp against the
	// server clock, which is the clock Pilot is synced to. Recomputing from
	// Date.now() would inherit whatever the browser's clock and timezone say.
	let age = lu.age_seconds;
	let is_stale = lu.is_stale;
	if (age === null || age === undefined) {
		age = lu.epoch ? Math.max(0, Math.floor(Date.now() / 1000) - lu.epoch) : null;
	}
	if (is_stale === null || is_stale === undefined) {
		is_stale = age === null || age > (d.stale_after_minutes || 15) * 60;
	}

	const ign_reported = st.ignition !== null && st.ignition !== undefined && st.ignition !== "";
	const ign_on = st.ignition === 1 || st.ignition === "1" || st.ignition === true;
	const has_fix =
		loc.lat !== null && loc.lat !== undefined && loc.lon !== null && loc.lon !== undefined;
	// Plain parseInt, not frappe.utils.cint -- cint() is a global in frappe's
	// JS, it does not hang off frappe.utils (that is the Python namespace).
	const sats = parseInt(loc.sats, 10) || 0;
	const compass = pilot_compass(st.direction);
	const map_id = "pilot-map-" + frappe.utils.get_random(8);

	// ---- the installation checklist ----------------------------------------
	// Status never rides on colour alone: every row carries an icon AND a word
	// AND the colour, so it survives colourblindness, greyscale print and
	// forced-colours mode.
	const ICONS = { ok: "✓", warn: "!", bad: "✕", na: "–" };
	const TONES = {
		ok: "var(--green-600, #16794c)",
		warn: "var(--orange-600, #b25000)",
		bad: "var(--red-600, #c0341d)",
		na: "var(--text-muted)",
	};
	const WORDS = { ok: __("OK"), warn: __("Check"), bad: __("Fail"), na: __("n/a") };

	// `opts.id` makes a row addressable so it can be rewritten live (the
	// ignition test does this); `opts.action` renders a control on the right edge.
	const check_row = (tone, label, value, hint, opts) => {
		opts = opts || {};
		return `
		<tr style="border-top:1px solid var(--border-color)"${opts.id ? ` id="${opts.id}"` : ""}>
			<td class="pilot-check-status" style="width:78px;padding:9px 0;vertical-align:top">
				<span style="display:inline-flex;align-items:center;gap:5px;font-weight:600;
							 font-size:11px;color:${TONES[tone]}">
					<span style="font-size:13px;line-height:1">${ICONS[tone]}</span>${WORDS[tone]}
				</span>
			</td>
			<td style="width:130px;padding:9px 0;vertical-align:top;color:var(--text-muted)">${label}</td>
			<td class="pilot-check-value" style="padding:9px 0;vertical-align:top">
				<b>${value}</b>
				${hint ? `<div style="font-size:11px;color:var(--text-muted);margin-top:2px">${hint}</div>` : ""}
			</td>
			<td class="pilot-check-action" style="padding:9px 0 9px 10px;vertical-align:top;
					text-align:right;white-space:nowrap">${opts.action || ""}</td>
		</tr>`;
	};

	// Status chip markup, reused when the ignition row rewrites itself.
	const chip = (tone) =>
		`<span style="display:inline-flex;align-items:center;gap:5px;font-weight:600;
					  font-size:11px;color:${TONES[tone]}">
			<span style="font-size:13px;line-height:1">${ICONS[tone]}</span>${WORDS[tone]}
		 </span>`;

	const gsm = pilot_find_sensor(d, /gsm|gprs|signal|network/i);
	const batt = pilot_find_sensor(d, /batt|volt|power|vbat|supply/i);
	const sensor_count = pilot_all_sensors(d).length;

	const checks = [];

	// 1. Is it talking to Pilot at all? Everything else is meaningless if not.
	checks.push(
		check_row(
			is_stale ? "warn" : "ok",
			__("Reporting"),
			is_stale ? __("Last seen {0}", [pilot_ago(age)]) : __("Live, {0}", [pilot_ago(age)]),
			is_stale
				? __("No update for longer than {0} min — check power and GSM antenna.", [
						d.stale_after_minutes,
				  ])
				: lu.epoch
				? __("Last fix {0}", [pilot_epoch_text(lu.epoch)])
				: ""
		)
	);

	// 2. GPS fix quality. A unit buried under metal reports few satellites.
	checks.push(
		check_row(
			!has_fix ? "bad" : sats && sats < 5 ? "warn" : "ok",
			__("GPS Fix"),
			!has_fix
				? __("No position")
				: __("{0} satellites", [sats || "?"]) + " · " + esc(loc.lat + ", " + loc.lon),
			!has_fix
				? __("Device has no GPS lock — reposition the antenna with a clear view of the sky.")
				: sats && sats < 5
				? __("Weak lock — reposition the GPS antenna.")
				: ""
		)
	);

	// 3. Ignition wiring. Reporting a value only proves the field exists -- it
	// does NOT prove the ACC wire is connected, because a disconnected input
	// reports a permanent OFF quite happily. The only real proof is that the
	// value FOLLOWS the key. "Check Now" automates that: it watches Pilot until
	// the state flips, instead of a phone call to the technician.
	checks.push(
		check_row(
			ign_reported ? "ok" : "warn",
			__("Ignition"),
			ign_reported ? (ign_on ? __("ON") : __("OFF")) : __("Not reported"),
			ign_reported
				? __("Reported value only — press Check Now to prove it follows the key.")
				: __("No ignition input — check the ACC wire."),
			{
				id: "pilot-check-ignition",
				action: ign_reported
					? `<button class="btn btn-xs btn-default pilot-ign-test">${__("Check Now")}</button>`
					: "",
			}
		)
	);

	// 4. Can it transmit?
	checks.push(
		check_row(
			gsm ? "ok" : "na",
			__("GSM Signal"),
			gsm ? esc(gsm.display || gsm.value) : __("Not reported"),
			gsm ? esc(gsm.name) : ""
		)
	);

	// 5. Power feed.
	checks.push(
		check_row(
			batt ? "ok" : "na",
			__("Power"),
			batt ? esc(batt.display || batt.value) : __("Not reported"),
			batt ? esc(batt.name) : __("This device does not report a battery sensor.")
		)
	);

	// 6. Anything wired to the inputs (reefer probes, door, etc.). The values
	// themselves are in the Sensor Readings grid below, so this row only has to
	// answer "is anything wired and reporting at all?".
	checks.push(
		check_row(
			sensor_count ? "ok" : "warn",
			__("Sensors"),
			__("{0} reporting", [sensor_count]),
			sensor_count ? __("Readings listed below.") : __("No sensor inputs are reporting.")
		)
	);

	// ---- status tiles ------------------------------------------------------
	// A handful of headline numbers reads as stat tiles, not a chart. Ignition
	// and satellites live in the checklist above, so they are not repeated here.
	const tile = (label, value, unit) => `
		<div style="flex:1 1 90px;min-width:90px;padding:8px 10px;border:1px solid var(--border-color);
					border-radius:var(--border-radius-md);background:var(--fg-color)">
			<div style="font-size:10px;letter-spacing:.6px;text-transform:uppercase;color:var(--text-muted)">${label}</div>
			<div style="font-size:20px;font-weight:600;line-height:1.25;margin-top:2px">${value}<span
				style="font-size:11px;font-weight:400;color:var(--text-muted);margin-left:3px">${unit || ""}</span></div>
		</div>`;

	const kpis = [
		tile(__("Speed"), st.speed === null || st.speed === undefined ? "&mdash;" : esc(st.speed), "km/h"),
		tile(__("Heading"), compass ? esc(compass) : "&mdash;",
			Number.isFinite(Number(st.direction)) ? esc(st.direction) + "°" : ""),
		tile(__("Altitude"), st.altitude === null || st.altitude === undefined ? "&mdash;" : esc(st.altitude), "m"),
		tile(__("Odometer"), dev.current_mileage === null || dev.current_mileage === undefined
			? "&mdash;" : esc(dev.current_mileage), "km"),
		tile(__("Parked"), esc(pilot_duration(st.parking)), ""),
	].join("");

	// A calm rule instead of a heavy heading: the eye finds the section without
	// the label competing with the data underneath it.
	const section = (title, extra) =>
		`<div style="display:flex;align-items:center;gap:10px;margin:22px 0 10px">
			<span style="font-size:11px;letter-spacing:.6px;text-transform:uppercase;
						 color:var(--text-muted);font-weight:600;white-space:nowrap">${title}</span>
			${extra ? `<span style="font-size:11px;color:var(--text-muted);white-space:nowrap">${extra}</span>` : ""}
			<span style="flex:1;height:1px;background:var(--border-color)"></span>
		</div>`;

	// One airy label-over-value cell. Used in a wrapping flex row, this reads
	// far faster than a bordered table for a handful of identity fields.
	const field = (label, value) => `
		<div style="flex:1 1 145px;min-width:145px">
			<div style="font-size:10px;letter-spacing:.5px;text-transform:uppercase;
						color:var(--text-muted)">${label}</div>
			<div style="margin-top:2px;word-break:break-word">${value}</div>
		</div>`;

	// One sensor reading. `secondary` is used by paired probes (temp / humidity)
	// so a probe stays a single object on screen rather than two loose numbers.
	const reading_tile = (name, primary, secondary, foot) => `
		<div style="flex:1 1 148px;min-width:148px;padding:9px 11px;border:1px solid var(--border-color);
					border-radius:var(--border-radius-md);background:var(--fg-color)">
			<div style="font-size:10px;letter-spacing:.5px;text-transform:uppercase;color:var(--text-muted);
						white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${name}</div>
			<div style="font-size:18px;font-weight:600;line-height:1.3;margin-top:2px">
				${primary}${
					secondary
						? `<span style="font-size:13px;font-weight:400;color:var(--text-muted)"> / ${secondary}</span>`
						: ""
				}
			</div>
			${foot ? `<div style="font-size:10px;color:var(--text-muted);margin-top:1px">${foot}</div>` : ""}
		</div>`;

	const kv = (rows) =>
		`<table class="table table-borderless" style="margin:0;font-size:12px">${rows
			.filter((r) => r)
			.map(
				([k, v]) =>
					`<tr><td style="width:42%;padding:3px 0;color:var(--text-muted)">${k}</td>
					     <td style="padding:3px 0;word-break:break-word">${v}</td></tr>`
			)
			.join("")}</table>`;

	// ---- sensor readings (quick view) --------------------------------------
	// Every reading Pilot sent, as one scannable grid. Paired probes render as
	// a single tile carrying both values, so nothing appears twice.
	const now_ep = diag.server_epoch || Math.floor(Date.now() / 1000);

	const probe_tiles = (d.probes || []).map((p) => {
		const t = p.temperature || {};
		const h = p.humidity || {};
		const ts = Math.max(t.ts || 0, h.ts || 0);
		return reading_tile(
			pilot_esc(p.label),
			t.display ? esc(t.display) : "&mdash;",
			h.display ? esc(h.display) : "&mdash;",
			(p.group ? esc(p.group) + " · " : "") +
				__("temp / humidity") +
				(ts ? " · " + esc(pilot_ago(now_ep - ts)) : "")
		);
	});

	const other_tiles = (d.others || []).map((o) =>
		reading_tile(
			esc(o.name),
			o.display ? esc(o.display) : o.value !== null && o.value !== undefined ? esc(o.value) : "&mdash;",
			null,
