// ---------------------------------------------------------------- ignition test
//
// Proves the ACC wire actually works, without anyone phoning the technician.
//
// Reads the current state, asks for the OPPOSITE, then re-reads IM until the
// flip is seen or the window closes. Flip observed -> pass. Nothing by the
// deadline -> FALSE.
//
// A disconnected ignition input reports a permanent, plausible-looking "OFF",
// which is why "the field has a value" is not evidence of anything. Only the
// transition is.
//
// THE POLL RATE IS NOT A CONSTANT HERE. IM allows roughly one live call per
// one-to-two minutes per account, so the interval comes from the snapshot
// (`poll_interval_seconds`, set in IM Settings) and the window is minutes long
// rather than Pilot's five. Hard-coding 5s would simply collect rate-limit
// errors and prove nothing.

// IM sends IGN as "ON"/"OFF"/"--"; the server has already reduced that to a
// tri-state boolean, but a raw value can still arrive on the refresh path.
function im_ign_bool(v) {
	if (v === true) return true;
	if (v === false) return false;
	if (v === null || v === undefined || v === "") return null;
	const s = String(v).trim().toLowerCase();
	if (["on", "1", "true", "yes"].includes(s)) return true;
	if (["off", "0", "false", "no"].includes(s)) return false;
	return null;
}

function im_mmss(ms) {
	const s = Math.max(0, Math.ceil(ms / 1000));
	return Math.floor(s / 60) + ":" + String(s % 60).padStart(2, "0");
}

function im_ignition_test(dlg, frm, d, helpers) {
	const $row = dlg.$body.find("#im-check-ignition");
	const $status = $row.find(".im-check-status");
	const $value = $row.find(".im-check-value");
	const $action = $row.find(".im-check-action");

	const start_state = im_ign_bool((d.state || {}).ignition);
	if (start_state === null) {
		frappe.msgprint({
			title: __("Ignition"),
			message: __("This device does not report an ignition value, so it cannot be tested."),
			indicator: "orange",
		});
		return;
	}

	// Both numbers are the server's, because the rate limit is the server's
	// problem to describe. The fallbacks only matter if an older payload is
	// somehow rendered by a newer script.
	const poll_ms = Math.max(30, Number(d.poll_interval_seconds) || 90) * 1000;
	const window_ms = Math.max(1, Number(d.ignition_window_minutes) || 10) * 60 * 1000;

	const want = !start_state;
	const want_word = want ? __("ON") : __("OFF");
	const from_word = start_state ? __("ON") : __("OFF");

	const started_at = Date.now();
	const deadline = started_at + window_ms;

	let ticks = 0;           // 1s UI ticks
	let polls = 0;           // completed IM reads
	let in_flight = false;
	let seen = start_state;  // most recent value IM reported
	let last_read_at = null; // desk-clock time of the last successful read
	let next_poll_at = Date.now() + poll_ms;
	let timer = null;

	const stop = () => {
		if (timer) clearInterval(timer);
		timer = null;
		dlg.$wrapper.off("hidden.bs.modal", stop);
	};

	// Polling must not outlive the dialog, or it keeps hitting IM unseen --
	// and on a rate-limited API that is not merely wasteful, it locks out the
	// next technician who opens the window.
	dlg.$wrapper.on("hidden.bs.modal", stop);

	const seen_word = () => (seen === null ? __("unknown") : seen ? __("ON") : __("OFF"));

	const render = () => {
		const left = deadline - Date.now();
		const pct = Math.min(100, ((Date.now() - started_at) / window_ms) * 100);
		const next_in = Math.max(0, Math.ceil((next_poll_at - Date.now()) / 1000));
		$value.html(`
			<div style="font-size:14px;font-weight:600;color:var(--text-color)">
				${__("Turn the ignition {0} now", [want_word])}
			</div>
			<div style="height:4px;border-radius:2px;background:var(--control-bg);margin:7px 0 5px;overflow:hidden">
				<div style="height:100%;width:${pct}%;background:var(--blue-500,#2490ef);transition:width .9s linear"></div>
			</div>
			<div style="font-size:11px;color:var(--text-muted)">
				${__("Watching IM")} · ${im_mmss(left)} ${__("left")} ·
				${__("{0} checks", [polls])} ·
				${__("next in {0}s", [next_in])} ·
				${__("currently reading")} <b>${seen_word()}</b>
			</div>
			<div style="font-size:10px;color:var(--text-muted);margin-top:2px">
				${__("IM allows about one live call per minute, so this re-reads every {0}s.", [
					Math.round(poll_ms / 1000),
				])}
			</div>`);
		$action.html(`<button class="btn btn-xs btn-default im-ign-stop">${__("Stop")}</button>`);
		$action.find(".im-ign-stop").on("click", () => {
			stop();
			finish(null);
		});
	};

	// Whatever the verdict, close by stating the value IM actually handed back.
	// Pass/fail answers "is the wire good?"; this answers "what is the ignition
	// doing right now?", which is what he checks against the key.
	const state_tail = () => `
		<div style="font-size:11px;margin-top:5px;padding-top:5px;
					border-top:1px dashed var(--border-color)">
			${__("State received from IM")}: <b>${seen_word()}</b>
			<span style="color:var(--text-muted)">
				· ${__("{0} checks", [polls])}${
					last_read_at ? " · " + __("last read {0}", [last_read_at]) : ""
				}
			</span>
		</div>`;

	// result: true = flipped, false = timed out, null = cancelled
	const finish = (result) => {
		stop();
		const secs = Math.round((Date.now() - started_at) / 1000);

		if (result === true) {
			$status.html(helpers.chip("ok"));
			$value.html(
				`<b style="color:var(--green-600,#16794c)">${__("TRUE")} — ${__(
					"ignition follows the key"
				)}</b>
				 <div style="font-size:11px;color:var(--text-muted);margin-top:2px">
					${__("Changed {0} → {1} after {2}s ({3} checks). The ACC wire is working.",
						[from_word, want_word, secs, polls])}
				 </div>
				 ${state_tail()}`
			);
		} else if (result === false) {
			$status.html(helpers.chip("bad"));
			$value.html(
				`<b style="color:var(--red-600,#c0341d)">${__("FALSE")} — ${__(
					"ignition did not change"
				)}</b>
				 <div style="font-size:11px;color:var(--text-muted);margin-top:2px">
					${__("Still {0} after {1} and {2} checks.", [from_word, im_mmss(window_ms), polls])}
					${__("Check the ACC wire, the fuse, and that the key was actually turned.")}
				 </div>
				 ${state_tail()}`
			);
		} else {
			$status.html(helpers.chip("warn"));
			$value.html(
				`<b>${__("Test stopped")}</b>
				 <div style="font-size:11px;color:var(--text-muted);margin-top:2px">
					${__("Stopped after {0}s and {1} checks — result unknown.", [secs, polls])}
				 </div>
				 ${state_tail()}`
			);
		}

		$action.html(`<button class="btn btn-xs btn-default im-ign-test">${__("Check Again")}</button>`);
		$action.find(".im-ign-test").on("click", () => im_ignition_test(dlg, frm, d, helpers));
	};

	const poll = () => {
		// Never stack requests: if IM is slow, skip this slot rather than
		// queueing calls that all land at once and trip the rate limit.
		if (in_flight) return;
		in_flight = true;
		next_poll_at = Date.now() + poll_ms;

		frappe.call({
			method: "app_apis.im_connector.get_snapshot",
			args: { ticket: frm.doc.name },
			// No freeze: the dialog must stay readable while this runs.
			callback(r) {
				in_flight = false;
				polls++;
				const msg = r && r.message;
				if (!msg) return;

				const cur = im_ign_bool((msg.state || {}).ignition);
				if (cur !== null) {
					seen = cur;
					last_read_at = frappe.datetime.now_time();
				}

				if (cur === want) {
					finish(true);
					return;
				}
				render();
			},
			error() {
				// A single failed read should not abort a multi-minute test.
				in_flight = false;
				polls++;
			},
		});
	};

	render();
	poll(); // read immediately so the first result is not a full interval away

	timer = setInterval(() => {
		ticks++;
		if (Date.now() >= deadline) {
			finish(false);
			return;
		}
		render();
		if (Date.now() >= next_poll_at) poll();
	}, 1000);
}

// ---------------------------------------------------------------- map

// The map instance for the open dialog, so the track overlay can find it.
let im_map_instance = null;

function im_render_map(map_id, d) {
	const loc = d.location || {};
	const st = d.state || {};
	const dev = d.device || {};

	// Runs more than once on purpose (see the scheduling at the bottom): the
	// _leaflet_id guard makes every call after the first a no-op.
	const init = () => {
		const el = document.getElementById(map_id);
		if (!el || el._leaflet_id) return;

		try {
			im_map_instance = im_build_map(el, map_id, loc, st, dev);
		} catch (e) {
			// Never leave an unexplained grey rectangle: say what went wrong
			// and still give the reader a way to see the position.
			console.error("[im] map failed to render", e);
			el.innerHTML =
				`<div class="text-muted" style="padding:16px">
					${__("Map could not be drawn")}: ${frappe.utils.escape_html(String(e.message || e))}.
					<a target="_blank" rel="noopener noreferrer"
					   href="https://www.openstreetmap.org/?mlat=${encodeURIComponent(loc.lat)}&mlon=${encodeURIComponent(loc.lon)}">
					   ${__("Open map")}</a>
				 </div>`;
		}
	};

	// A Leaflet map sizes itself from its container, and the container has no
	// layout until the modal's fade-in finishes -- initialising too early
	// yields a 0x0 map and a grey box. Hook the modal's own "shown" event and
	// keep two timed retries as a fallback for when that event is missed.
	$(document).one("shown.bs.modal", init);
	setTimeout(init, 150);
	setTimeout(init, 700);
}

function im_build_map(el, map_id, loc, st, dev) {
	if (typeof L === "undefined" || !L.map) {
		throw new Error(__("Leaflet is not loaded"));
	}

	const defaults = (frappe.utils.map_defaults || {}).tiles || {};
	const map = L.map(map_id, { scrollWheelZoom: false }).setView([loc.lat, loc.lon], 15);

	const street = L.tileLayer(
		(defaults.default_tile || {}).url || "https://tile.openstreetmap.org/{z}/{x}/{y}.png",
		(defaults.default_tile || {}).options || {}
	);
	const satellite = defaults.satellite_tile
		? L.tileLayer(defaults.satellite_tile.url, defaults.satellite_tile.options)
		: null;

	street.addTo(map);
	if (satellite) {
		L.control.layers({ [__("Street")]: street, [__("Satellite")]: satellite }, {}).addTo(map);
	}

	// A divIcon rather than the default PNG marker: frappe's bundled marker
	// images are named "leafletmarker-icon.png", which does not match the
	// "marker-icon.png" Leaflet derives from imagePath, so the stock icon
	// 404s. Drawing the marker in CSS also lets it carry the heading.
	const heading = Number(st.direction);
	const arrow = Number.isFinite(heading)
		? `<div style="position:absolute;left:50%;top:50%;width:0;height:0;
					transform:translate(-50%,-50%) rotate(${heading}deg)">
				<div style="position:absolute;left:-6px;top:-24px;width:0;height:0;
							border-left:6px solid transparent;border-right:6px solid transparent;
							border-bottom:10px solid #2490ef"></div>
		   </div>`
		: "";

	const icon = L.divIcon({
		className: "",
		iconSize: [22, 22],
		iconAnchor: [11, 11],
		html: `<div style="position:relative;width:22px;height:22px">
				${arrow}
				<div style="position:absolute;inset:0;border-radius:50%;background:#2490ef;
							border:2px solid #fff;box-shadow:0 0 0 1px rgba(0,0,0,.25)"></div>
			   </div>`,
	});

	const popup = [
		`<b>${im_esc(dev.name || dev.vehicle_name || dev.imei)}</b>`,
		`${__("Speed")}: ${im_esc(st.speed)} km/h`,
		`${__("Ignition")}: ${st.ignition === true ? __("ON") : st.ignition === false ? __("OFF") : "—"}`,
		`${loc.lat}, ${loc.lon}`,
	].join("<br>");

	L.marker([loc.lat, loc.lon], { icon }).addTo(map).bindPopup(popup);

	// Accuracy is not reported, so draw nothing implying it. A light circle
	// only marks the point at low zoom.
	L.circle([loc.lat, loc.lon], {
		radius: 40,
		color: "#2490ef",
		weight: 1,
		opacity: 0.5,
		fillOpacity: 0.08,
	}).addTo(map);

	// The container may still have been mid-animation when this ran.
	map.invalidateSize();
	setTimeout(() => map.invalidateSize(), 300);

	return map;
}

// ---------------------------------------------------------------- track overlay
//
// Draws the last six hours from `?token=getVehicleTrackLogs` over the live
// position. IM does not document that endpoint's response shape, so the server
// extracts points defensively and may legitimately return none -- which this
// reports as "no points", never as a silent empty map.

function im_load_track(dlg, frm, $btn) {
	const $note = dlg.$body.find(".im-track-note");
	$btn.prop("disabled", true).text(__("Loading…"));
	$note.text("");

	frappe.call({
		method: "app_apis.im_connector.get_track_logs",
		args: { ticket: frm.doc.name, hours: 6 },
		callback(r) {
			$btn.prop("disabled", false).text(__("Show Track (6h)"));
			const t = (r && r.message) || {};
			const pts = t.points || [];

			if (!pts.length) {
				$note.text(
					__("IM returned no track points for {0} between {1} and {2}.", [
						t.vehicle_no,
						t.start_date,
						t.end_date,
					])
				);
				return;
			}
			if (!im_map_instance) {
				$note.text(__("{0} points returned, but the map is not drawn.", [pts.length]));
				return;
			}

			const line = pts.map((p) => [p.lat, p.lon]);
			const poly = L.polyline(line, { color: "#7c3aed", weight: 3, opacity: 0.8 });
			poly.addTo(im_map_instance);
			// Start of the run, so the direction of travel is readable at a glance.
			L.circleMarker(line[0], {
				radius: 5,
				color: "#7c3aed",
				fillColor: "#fff",
				fillOpacity: 1,
				weight: 2,
			})
				.addTo(im_map_instance)
				.bindPopup(`<b>${__("Track start")}</b><br>${im_esc(pts[0].time_text || "")}`);

			im_map_instance.fitBounds(poly.getBounds(), { padding: [20, 20] });
			$note.text(
				__("{0} points · {1} → {2}", [pts.length, t.start_date, t.end_date])
			);
			$btn.prop("disabled", true);
		},
		error() {
			$btn.prop("disabled", false).text(__("Show Track (6h)"));
		},
	});
}

// "Valuation Link" toolbar button for xticket.
//
// One dialog does everything an operator needs to ask a customer for feedback:
//   - the message and the bare link, both editable
//   - a number picked from the ticket, or typed in when the ticket has none
//   - copy buttons for pasting anywhere, and Send for going straight to Chatwoot
//
// One message box, not two. The messages carry Arabic and English together now,
// so there is nothing to choose between and no language picker here -- what is
// in the box is exactly what the customer receives.
//
// The box and the link come from ONE server call on purpose. The message text
// lives in App APIs -> Chatwoot Messages, and the link is minted once and pasted
// into it -- a second call would give the operator two boxes carrying two
// different tokens, expiring seconds apart.
//
// The link is public by design -- it carries a signed token instead of
// requiring an account -- so "Open as Customer" shows exactly what the customer
// sees. Open it in a private window to prove it works with no session at all.
//
// Every press mints a fresh link that dies 24 hours later, so re-sending is
// always safe: the customer gets a full day from the moment you hand it over.

// Full international form: a leading +, a country code that cannot start with
// zero, and 8-15 digits total. Deliberately strict -- Chatwoot accepts a local
// number and simply never delivers it.
const E164 = /^\+[1-9]\d{7,14}$/;

frappe.ui.form.on("xticket", {
	refresh(frm) {
		if (frm.is_new()) return;

		frm.add_custom_button(__("Valuation Link"), () => {
			frappe.call({
				method: "app_apis.chatwoot_connector.preview_message",
				args: { ticket: frm.doc.name, template: "valuation" },
				freeze: true,
				freeze_message: __("Building link…"),
				callback(r) {
					const d = (r && r.message) || {};

					if (!d.ok) {
						frappe.msgprint({
							title: __("Valuation Link"),
							message: d.msg || __("Could not build the link."),
							indicator: "red",
						});
						return;
					}

					show_dialog(frm, d);
				},
			});
		});
	},
});

function clean_number(value) {
	// Spaces, dashes and brackets are how people write numbers; strip them
	// before judging the shape, and keep a leading + if there is one.
	return String(value || "").replace(/[\s\-().]/g, "");
}

function show_dialog(frm, d) {
	const OTHER = "__other__";
	const has_phones = d.phones && d.phones.length > 0;

	const copy = (value, what) => {
		if (!value) return;
		frappe.utils.copy_to_clipboard(value);
		frappe.show_alert({ message: __("{0} copied", [what]), indicator: "green" });
	};

	const fields = [
		{ fieldtype: "HTML", fieldname: "info" },

		{ fieldtype: "Section Break", label: __("Message") },
		{
			fieldtype: "Small Text",
			fieldname: "msg",
			// No label: the section heading already says what this is, and a
			// label here just pushes the text down.
			default: d.message,
		},
		{
			fieldtype: "Button",
			fieldname: "copy_msg",
			label: __("Copy Message"),
			click: () => copy(dialog.get_value("msg"), __("Message")),
		},

		{ fieldtype: "Section Break", label: __("Link Only") },
		{ fieldtype: "Small Text", fieldname: "link", default: d.link },
		{
			fieldtype: "Button",
			fieldname: "copy_link",
			label: __("Copy Link"),
			click: () => copy(dialog.get_value("link"), __("Link")),
		},

		{ fieldtype: "Section Break", label: __("Send via Chatwoot") },
		{
			fieldtype: "Select",
			fieldname: "pick",
			label: __("Send to"),
			// "Other number…" is always offered: the number on the ticket is
			// often the driver's, and whoever should rate the work is the
			// person the operator actually spoke to.
			options: (d.phones || [])
				.map((p) => ({ value: p.phone, label: `${p.label} — ${p.phone}` }))
				.concat([{ value: OTHER, label: __("Other number…") }]),
			default: has_phones ? d.phones[0].phone : OTHER,
			change() {
				const other = dialog.get_value("pick") === OTHER;
				dialog.set_df_property("manual", "hidden", !other);
				dialog.set_df_property("manual", "reqd", other);
				if (other) dialog.fields_dict.manual.$input.focus();
			},
		},
		{
			fieldtype: "Data",
			fieldname: "manual",
			label: __("Mobile number"),
			description: __(
				"Full international form, including the country code — for example +966512345678."
			),
			hidden: has_phones,
			reqd: !has_phones,
		},
		{
			fieldtype: "Button",
			fieldname: "send",
			label: __("Send Now"),
			click: () => do_send(frm, d, dialog, OTHER),
		},
	];

	const dialog = new frappe.ui.Dialog({
		title: __("Valuation Link"),
		size: "large",
		fields: fields,
		primary_action_label: __("Open as Customer"),
		primary_action() {
			window.open(dialog.get_value("link") || d.link, "_blank", "noopener");
		},
	});

	const esc = (v) => frappe.utils.escape_html(String(v || "—"));

	// Worth being loud about when it is missing: about 40% of tickets carry no
	// usable number, and the operator should know before hunting for one.
	const phone_note = has_phones
		? `<div><b>${__("Mobile")}:</b> <span dir="ltr">${esc(d.phones[0].phone)}</span>
		     <span style="color:var(--text-muted)">(${esc(d.phones[0].label)})</span></div>`
		: `<div style="margin-top:8px;padding:8px 10px;border-radius:6px;
		            background:#fff7ed;border:1px solid #fed7aa">
		     <b>${__("This ticket has no mobile number")}</b> —
		     ${__("type one below before sending.")}
		   </div>`;

	dialog.fields_dict.info.$wrapper.html(`
		<div style="font-size:13px;margin-bottom:10px">
			<div><b>${__("Ticket")}:</b> ${esc(d.ticket)}</div>
			<div><b>${__("Customer")}:</b> ${esc(d.customer)}</div>
			${phone_note}
			<div style="margin-top:8px">
				<span class="indicator-pill orange">
					${__("Expires")} ${esc(d.expires_on)}
				</span>
				${
					d.can_send
						? ""
						: `<span class="indicator-pill red" style="margin-inline-start:6px">
							${__("Chatwoot not ready")}</span>`
				}
			</div>
			<div style="margin-top:8px;color:var(--text-muted)">
				${__(
					"Message text comes from App APIs → Chatwoot Messages, in Arabic and English together. Anyone with this link can open it without an account, and only for this ticket. It stops working after {0} hours — press the button again for a fresh one.",
					[d.valid_hours || 24]
				)}
			</div>
		</div>
	`);

	dialog.show();

	// "auto" rather than a fixed direction: the box holds Arabic and English in
	// one block, and the browser lays each line out by its own first letter.
	// Forcing rtl would drag the English lines' punctuation to the wrong end.
	dialog.fields_dict.msg.$input.attr("dir", "auto");
	dialog.fields_dict.link.$input.attr("dir", "ltr");
	dialog.fields_dict.manual.$input
		.attr("dir", "ltr")
		.attr("placeholder", "+966512345678");

	// Small Text defaults to three rows; these messages are longer than that.
	dialog.fields_dict.msg.$input.attr("rows", 10);
	dialog.fields_dict.link.$input.attr("rows", 2);
}

function do_send(frm, d, dialog, OTHER) {
	if (!d.can_send) {
		frappe.msgprint({
			title: __("Cannot send"),
			message: d.cannot_send_reason || __("Chatwoot is not ready."),
			indicator: "orange",
		});
		return;
	}

	const picked = dialog.get_value("pick");
	const destination = clean_number(
		!picked || picked === OTHER ? dialog.get_value("manual") : picked
	);

	if (!destination) {
		frappe.msgprint({
			title: __("No number"),
			message: __("Enter a mobile number first."),
			indicator: "orange",
		});
		return;
	}

	// Checked here rather than trusted to the server: a number the server
	// "fixes" by guessing a country code is a message delivered to whoever
	// happens to own that number abroad.
	if (!E164.test(destination)) {
		frappe.msgprint({
			title: __("Check the number"),
			message: __(
				"{0} is not a full international number. Include the country code, starting with + — for example +966512345678.",
				[frappe.utils.escape_html(destination)]
			),
			indicator: "red",
		});
		return;
	}

	// The operator may have edited the message in the box above, so send that
	// text rather than re-rendering the template server-side and quietly
	// discarding their edit.
	const text = dialog.get_value("msg");

	frappe.confirm(
		__("Send this message to {0}?", [`<b dir="ltr">${destination}</b>`]),
		() => {
			frappe.call({
				method: "app_apis.chatwoot_connector.send_ticket_message",
				args: {
					ticket: frm.doc.name,
					template: "valuation",
					phone: destination,
					text: text,
				},
				freeze: true,
				freeze_message: __("Sending…"),
				callback(r) {
					const res = (r && r.message) || {};

					if (res.ok) {
						frappe.show_alert(
							{
								message: __("Sent to {0}", [res.phone || destination]),
								indicator: "green",
							},
							7
						);
						dialog.hide();
						return;
					}

					frappe.msgprint({
						title: __("Not sent"),
						message: `${res.msg || __("Unknown error")}<br><small>${__("code")}: ${
							res.code || "—"
						}</small>`,
						indicator: "red",
					});
				},
			});
		}
	);
}

// Bottom-right toast when an automatic customer message goes out.
//
// The send happens in a background worker seconds after the ticket is saved,
// so there is no ajax response left to report into -- the server pushes
// `app_apis_message_sent` over the realtime socket and this listens for it.
//
// SOURCE OF TRUTH for the Client Script `xticket-message-toast`. Mirrored
// byte-for-byte into fixtures/client_script.json; edit here, then copy across.

frappe.provide("app_apis");

// Registering inside `refresh` means every form load would add another handler
// and the operator would get two toasts, then three. The flag pins it to one
// per page load -- and because the listener lives on the global socket rather
// than the form, it keeps working after they navigate away from the ticket.
if (!app_apis._message_toast_bound) {
	app_apis._message_toast_bound = true;

	// What the operator calls each message. Kept here rather than sent from the
	// server so the toast follows the desk language, not the customer's.
	//
	// The engineer's messages are named as such rather than shown with a
	// recipient field beside them: a toast is read in a second, and "Feedback
	// link sent" next to "Engineer job assignment sent" needs no explaining.
	const LABELS = {
		accepted: __("Acceptance message"),
		working: __("Work started message"),
		valuation: __("Feedback link"),
		tech_accepted: __("Engineer job assignment"),
		tech_working: __("Engineer work-started notice"),
		tech_done: __("Engineer job-closed notice"),
	};

	const LOOK = {
		Sent: { indicator: "green", icon: "✅", seconds: 5 },
		Failed: { indicator: "red", icon: "⚠️", seconds: 10 },
		Skipped: { indicator: "orange", icon: "⏭️", seconds: 7 },
	};

	frappe.realtime.on("app_apis_message_sent", function (d) {
		if (!d || !d.ticket) return;

		const look = LOOK[d.status] || LOOK.Skipped;
		const label = LABELS[d.template] || d.template || __("Message");

		let line;
		if (d.status === "Sent") {
			line = __("{0} sent to {1}", [label, frappe.utils.escape_html(d.phone || "-")]);
		} else if (d.status === "Failed") {
			line = __("{0} could NOT be sent", [label]);
		} else {
			line = __("{0} skipped", [label]);
		}

		// The ticket is a link: a toast about a message is only useful if you
		// can get to the ticket it was about.
		const ticket = frappe.utils.escape_html(d.ticket);
		const href = `/app/xticket/${encodeURIComponent(d.ticket)}`;
		let body = `${look.icon} ${line}<br><a href="${href}"><b>${ticket}</b></a>`;

		if (d.reason) {
			body += `<br><span style="opacity:.75">${frappe.utils.escape_html(String(d.reason).slice(0, 160))}</span>`;
		}

		frappe.show_alert({ message: body, indicator: look.indicator }, look.seconds);
	});
}

// "Check Pilot 2" toolbar button for xticket -- the SECOND, unrelated Pilot
// estate (see app_apis.connector._settings(account=2) / App APIs > Pilot 2).
// Same widget as "Check Pilot" (xticket-check-pilot): checklist, map,
// sensors, "Show all", live ignition test -- just pointed at a different
// estate's per-customer connection. A SEPARATE Client Script record, not a
// parameter on the first one, so nothing here can break the WSL button, and
// every identifier below is prefixed pilot2_ / PILOT2_ / "pilot2-" so the two
// scripts can run on the same page without colliding (Client Scripts share
// one global scope in the browser -- see xticket-check-im for the same
// pattern with its im_ prefix).
//
//     this script  ->  app_apis.connector.get_snapshot(..., account=2)  ->  Pilot (estate 2)
//
// Installed as a Client Script record (dt=xticket, view=Form) so it is
// editable from the desk at /app/client-script.

frappe.ui.form.on("xticket", {
	refresh(frm) {
		if (frm.is_new()) return;

		// Same "Check" group as "xticket-check-pilot" / "xticket-check-im" --
		// Frappe merges same-named groups into one dropdown at runtime
		// regardless of which Client Script registered each item, so this
		// lands next to the other two under a single button.
		frm.add_custom_button(__("Pilot 2"), () => pilot2_check(frm), __("Check"));
	},
});

// Titles the app raises when the lookup simply found nothing. Kept as an
// explicit list rather than a keyword match: an account rejected with 401 also
// returns no vehicle, and calling a bad credential "not found" sends a
// technician hunting for a device when the login is what is broken.
const PILOT2_NOT_FOUND_TITLES = ["Pilot: No Data", "No IMEI", "No Pilot Account"];

// The app's frappe.throw arrives as `_server_messages`: a JSON string holding an
// array of JSON strings, each {title, message, indicator}.
function pilot2_server_messages(r) {
	try {
		return JSON.parse(r._server_messages || "[]").map((m) => {
			try {
				return JSON.parse(m);
			} catch (e) {
				return { message: String(m) };
			}
		});
	} catch (e) {
		return [];
	}
}

// Pull the IMEI back out of the failure text so the "Use Admin" fallback
// button knows what to ask the admin sweep for. connector.py's failure-detail
// message is always built as "...for IMEI {imei} on node {node}.", so this is
// a stable contract with the server, not a guess.
function pilot2_extract_imei(text) {
	const m = /\bIMEI\s+(\d{6,20})\b/i.exec(text || "");
	return m ? m[1] : null;
}

// Manual, explicit fallback -- never automatic. Re-sweeps whichever admin
// estates are enabled (the search is by IMEI, not by which estate a device
// "should" belong to) and renders the result through the SAME dialog as a
// normal customer-login read.
function pilot2_admin_fallback(frm, imei) {
	frappe.call({
		method: "app_apis.pilot_admin.get_vehicle_live_admin",
		args: { imei },
		freeze: true,
		freeze_message: __("Sweeping the full Pilot estate via the admin account (30–90s)…"),
		callback(r) {
			if (!r || !r.message) {
				frappe.msgprint({
					title: __("Pilot"),
					message: __("The admin sweep returned an empty response."),
					indicator: "orange",
				});
				return;
			}
			pilot2_show(frm, r.message);
		},
	});
}

// Restate an empty result as a plain "not found" notice.
//
// This is registered as an `error_handlers` entry rather than an `error` or
// `always` callback, and that is the whole trick: frappe only draws its own
// dialog when NO handler is registered for the exception type --
//
//     if (handlers.length === 0) { frappe.hide_msgprint(); frappe.msgprint(messages); }
//         -- frappe/public/js/frappe/request.js
//
// so registering one replaces frappe's dialog outright instead of racing it.
// The consequence is that this function now owns EVERY ValidationError from the
// call: any branch that does not print something swallows the message, which is
// why the last branch re-renders exactly what frappe would have shown.
// `frm` is bound in by pilot2_check below (`error_handlers` only ever passes
// frappe the response object), so the "Use Admin" button knows which form to
// render into.
// A ticket names its device in whichever field the job was created through, so
// the first value that looks like a device serial wins. Used only as a fallback
// for the admin sweep, so a wrong guess costs a slow lookup, never a wrong read.
function pilot2_ticket_imei(frm) {
	const d = (frm && frm.doc) || {};
	const candidates = [
		d.device_serial_new, d.device_serial, d.device_id_link, d.device_id_scan, d.serial,
	];
	for (const c of candidates) {
		const m = /\b(\d{10,20})\b/.exec(String(c || ""));
		if (m) return m[1];
	}
	return null;
}

function pilot2_error_handler(r, frm) {
	const msgs = pilot2_server_messages(r);
	const title = (msgs[0] && msgs[0].title) || "";
	const body = msgs.map((m) => m.message || "").join("\n\n");

	// Folded away, not dropped: the raw server text is what made these dialogs
	// too long to read, but it is still the only thing that explains an
	// unexpected failure. Closed by default, so the dialog is one line.
	const detail = body
		? `<details style="margin-top:8px"><summary style="cursor:pointer;font-size:11px;
				color:var(--text-muted)">${__("Details")}</summary>
				<div style="margin-top:6px;font-size:11px;color:var(--text-muted);
					white-space:pre-wrap">${frappe.utils.escape_html(body)}</div></details>`
		: "";

	// Credentials are tested FIRST, on the body rather than the title. A run in
	// which every account was rejected with 401 still comes back titled
	// "Pilot: No Data", so matching the title alone would report a rejected
	// login as a missing device -- sending a technician to hunt for hardware
	// when the account is what is broken.
	if (/\b401\b|unauthor|credential|rejected/i.test(body + title)) {
		// Fall back to the ticket's own device serial when the failure text
		// carries no IMEI, so the admin sweep is offered on EVERY rejected
		// login -- not only the ones that happened to name the device.
		const imei = pilot2_extract_imei(body + title) || pilot2_ticket_imei(frm);
		frappe.msgprint({
			title: __("Pilot 2 Login Rejected"),
			indicator: "red",
			message:
				`<div style="font-size:13px"><b>${__(
					"Login rejected by Pilot 2 \u2014 not a missing device."
				)}</b></div>` + detail,
			// Manual fallback only -- never automatic. Hidden only when neither
			// the failure text nor the ticket names a device.
			primary_action: imei
				? {
						label: __("Use Admin (slow — 30–90s)"),
						action: () => pilot2_admin_fallback(frm, imei),
				  }
				: null,
		});
		return;
	}

	// Reached the platform, it simply holds nothing for this device. Red, not
	// orange: a device the platform cannot see is a fault to act on, and it is
	// the answer the technician opened this dialog for.
	if (PILOT2_NOT_FOUND_TITLES.some((t) => title.indexOf(t) !== -1)) {
		frappe.msgprint({
			title: __("No Data"),
			indicator: "red",
			message:
				`<div style="font-size:14px;color:var(--red-600,#c0392b)"><b>${__(
					"No data"
				)}</b></div>
				<div style="margin-top:4px;font-size:12px;color:var(--text-muted)">${__(
					"Reached Pilot 2; it holds nothing for this device."
				)}</div>` + detail,
		});
		return;
	}

	// Not ours to interpret -- render exactly what frappe would have, so
	// registering this handler can never silently swallow a message.
	if (msgs.length) {
		msgs.forEach((m) => frappe.msgprint(m));
	} else {
		frappe.msgprint({
			title: __("Pilot"),
			indicator: "red",
			message: __("The request failed and Pilot returned no message."),
		});
	}
}

function pilot2_check(frm) {
	frappe.call({
		method: "app_apis.connector.get_snapshot",
		args: { ticket: frm.doc.name, account: 2 },
		freeze: true,
		freeze_message: __("Contacting Pilot…"),
		error_handlers: { ValidationError: (r) => pilot2_error_handler(r, frm) },
		callback(r) {
			if (!r || !r.message) {
				frappe.msgprint({
					title: __("Pilot"),
					message: __("Pilot returned an empty response."),
					indicator: "orange",
				});
				return;
			}
			pilot2_show(frm, r.message);
		},
	});
}

// ---------------------------------------------------------------- helpers

// Pilot HTML-encodes some strings ("Queen's Taste Bakery &amp; Sweets").
// Decode first, then escape for output -- decoding alone would be an XSS hole,
// escaping alone would show the reader a literal "&amp;".
function pilot2_decode(s) {
	const el = document.createElement("textarea");
	el.innerHTML = String(s);
	return el.value;
}

function pilot2_esc(v) {
	return frappe.utils.escape_html(pilot2_decode(v));
}

function pilot2_dash(v) {
	return v === null || v === undefined || v === "" ? "&mdash;" : pilot2_esc(v);
}

// Seconds -> "2h 5m" / "5m 12s" / "12s". Pilot reports `moving` and `parking`
// as counters in the current state, not as booleans.
function pilot2_duration(sec) {
	sec = Math.max(0, Math.floor(Number(sec) || 0));
	if (!sec) return "0s";
	const h = Math.floor(sec / 3600);
	const m = Math.floor((sec % 3600) / 60);
	const s = sec % 60;
	if (h) return `${h}h ${m}m`;
	if (m) return `${m}m ${s}s`;
	return `${s}s`;
}

function pilot2_ago(sec) {
	if (sec === null || sec === undefined) return __("unknown");
	sec = Math.max(0, Math.floor(sec));
	if (sec < 60) return __("{0}s ago", [sec]);
	if (sec < 3600) return __("{0}m ago", [Math.floor(sec / 60)]);
	if (sec < 86400) return __("{0}h ago", [Math.floor(sec / 3600)]);
	return __("{0}d ago", [Math.floor(sec / 86400)]);
}

function pilot2_epoch_text(epoch) {
	if (!epoch) return "";
	// frappe renders in the user's configured timezone, which is what the
	// reader expects to see -- not the raw UTC of the epoch.
	return frappe.datetime.str_to_user(
		frappe.datetime.convert_to_user_tz(
			moment.unix(Number(epoch)).utc().format("YYYY-MM-DD HH:mm:ss")
		)
	);
}

// 344 -> "NNW". Pilot sends heading in degrees on this account, but sends a
// literal string ("NE") on others, so pass non-numeric values straight through.
function pilot2_compass(dir) {
	const n = Number(dir);
	if (dir === null || dir === undefined || dir === "" || Number.isNaN(n)) {
		return dir ? String(dir) : null;
	}
	const pts = ["N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE",
		"S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW"];
	return pts[Math.round((n % 360) / 22.5) % 16];
}

// Every sensor Pilot reported, probes included, as one flat list.
function pilot2_all_sensors(d) {
	const all = (d.others || []).slice();
	(d.probes || []).forEach((p) => {
		if (p.temperature) all.push(p.temperature);
		if (p.humidity) all.push(p.humidity);
	});
	return all;
}

function pilot2_find_sensor(d, re) {
	return pilot2_all_sensors(d).find((s) => re.test(String(s.name || "")));
}

// ---------------------------------------------------------------- render

function pilot2_show(frm, d) {
	const esc = pilot2_esc;
	const dash = pilot2_dash;

	const st = d.state || {};
	const loc = d.location || {};
	const dev = d.device || {};
	const info = d.ticket_info || {};
	const diag = d.diagnostics || {};
	const lu = d.last_update || {};

	// Prefer the server's figures: it compares Pilot's timestamp against the
	// server clock, which is the clock Pilot is synced to. Recomputing from
	// Date.now() would inherit whatever the browser's clock and timezone say.
	let age = lu.age_seconds;
	let is_stale = lu.is_stale;
	if (age === null || age === undefined) {
		age = lu.epoch ? Math.max(0, Math.floor(Date.now() / 1000) - lu.epoch) : null;
	}
	if (is_stale === null || is_stale === undefined) {
		is_stale = age === null || age > (d.stale_after_minutes || 15) * 60;
	}

	const ign_reported = st.ignition !== null && st.ignition !== undefined && st.ignition !== "";
	const ign_on = st.ignition === 1 || st.ignition === "1" || st.ignition === true;
	const has_fix =
		loc.lat !== null && loc.lat !== undefined && loc.lon !== null && loc.lon !== undefined;
	// Plain parseInt, not frappe.utils.cint -- cint() is a global in frappe's
	// JS, it does not hang off frappe.utils (that is the Python namespace).
	const sats = parseInt(loc.sats, 10) || 0;
	const compass = pilot2_compass(st.direction);
	const map_id = "pilot2-map-" + frappe.utils.get_random(8);

	// ---- the installation checklist ----------------------------------------
	// Status never rides on colour alone: every row carries an icon AND a word
	// AND the colour, so it survives colourblindness, greyscale print and
	// forced-colours mode.
	const ICONS = { ok: "✓", warn: "!", bad: "✕", na: "–" };
	const TONES = {
		ok: "var(--green-600, #16794c)",
		warn: "var(--orange-600, #b25000)",
		bad: "var(--red-600, #c0341d)",
		na: "var(--text-muted)",
	};
	const WORDS = { ok: __("OK"), warn: __("Check"), bad: __("Fail"), na: __("n/a") };

	// `opts.id` makes a row addressable so it can be rewritten live (the
	// ignition test does this); `opts.action` renders a control on the right edge.
	const check_row = (tone, label, value, hint, opts) => {
		opts = opts || {};
		return `
		<tr style="border-top:1px solid var(--border-color)"${opts.id ? ` id="${opts.id}"` : ""}>
			<td class="pilot2-check-status" style="width:78px;padding:9px 0;vertical-align:top">
				<span style="display:inline-flex;align-items:center;gap:5px;font-weight:600;
							 font-size:11px;color:${TONES[tone]}">
					<span style="font-size:13px;line-height:1">${ICONS[tone]}</span>${WORDS[tone]}
				</span>
			</td>
			<td style="width:130px;padding:9px 0;vertical-align:top;color:var(--text-muted)">${label}</td>
			<td class="pilot2-check-value" style="padding:9px 0;vertical-align:top">
				<b>${value}</b>
				${hint ? `<div style="font-size:11px;color:var(--text-muted);margin-top:2px">${hint}</div>` : ""}
			</td>
			<td class="pilot2-check-action" style="padding:9px 0 9px 10px;vertical-align:top;
					text-align:right;white-space:nowrap">${opts.action || ""}</td>
		</tr>`;
	};

	// Status chip markup, reused when the ignition row rewrites itself.
	const chip = (tone) =>
		`<span style="display:inline-flex;align-items:center;gap:5px;font-weight:600;
					  font-size:11px;color:${TONES[tone]}">
			<span style="font-size:13px;line-height:1">${ICONS[tone]}</span>${WORDS[tone]}
		 </span>`;

	const gsm = pilot2_find_sensor(d, /gsm|gprs|signal|network/i);
	const batt = pilot2_find_sensor(d, /batt|volt|power|vbat|supply/i);
	const sensor_count = pilot2_all_sensors(d).length;

	const checks = [];

	// 1. Is it talking to Pilot at all? Everything else is meaningless if not.
	checks.push(
		check_row(
			is_stale ? "warn" : "ok",
			__("Reporting"),
			is_stale ? __("Last seen {0}", [pilot2_ago(age)]) : __("Live, {0}", [pilot2_ago(age)]),
			is_stale
				? __("No update for longer than {0} min — check power and GSM antenna.", [
						d.stale_after_minutes,
				  ])
				: lu.epoch
				? __("Last fix {0}", [pilot2_epoch_text(lu.epoch)])
				: ""
		)
	);

	// 2. GPS fix quality. A unit buried under metal reports few satellites.
	checks.push(
		check_row(
			!has_fix ? "bad" : sats && sats < 5 ? "warn" : "ok",
			__("GPS Fix"),
			!has_fix
				? __("No position")
				: __("{0} satellites", [sats || "?"]) + " · " + esc(loc.lat + ", " + loc.lon),
			!has_fix
				? __("Device has no GPS lock — reposition the antenna with a clear view of the sky.")
				: sats && sats < 5
				? __("Weak lock — reposition the GPS antenna.")
				: ""
		)
	);

	// 3. Ignition wiring. Reporting a value only proves the field exists -- it
	// does NOT prove the ACC wire is connected, because a disconnected input
	// reports a permanent OFF quite happily. The only real proof is that the
	// value FOLLOWS the key. "Check Now" automates that: it watches Pilot until
	// the state flips, instead of a phone call to the technician.
	checks.push(
		check_row(
			ign_reported ? "ok" : "warn",
			__("Ignition"),
			ign_reported ? (ign_on ? __("ON") : __("OFF")) : __("Not reported"),
			ign_reported
				? __("Reported value only — press Check Now to prove it follows the key.")
				: __("No ignition input — check the ACC wire."),
			{
				id: "pilot2-check-ignition",
				action: ign_reported
					? `<button class="btn btn-xs btn-default pilot2-ign-test">${__("Check Now")}</button>`
					: "",
			}
		)
	);

	// 4. Can it transmit?
	checks.push(
		check_row(
			gsm ? "ok" : "na",
			__("GSM Signal"),
			gsm ? esc(gsm.display || gsm.value) : __("Not reported"),
			gsm ? esc(gsm.name) : ""
		)
	);

	// 5. Power feed.
	checks.push(
		check_row(
			batt ? "ok" : "na",
			__("Power"),
			batt ? esc(batt.display || batt.value) : __("Not reported"),
			batt ? esc(batt.name) : __("This device does not report a battery sensor.")
		)
	);

	// 6. Anything wired to the inputs (reefer probes, door, etc.). The values
	// themselves are in the Sensor Readings grid below, so this row only has to
	// answer "is anything wired and reporting at all?".
	checks.push(
		check_row(
			sensor_count ? "ok" : "warn",
			__("Sensors"),
			__("{0} reporting", [sensor_count]),
			sensor_count ? __("Readings listed below.") : __("No sensor inputs are reporting.")
		)
	);

	// ---- status tiles ------------------------------------------------------
	// A handful of headline numbers reads as stat tiles, not a chart. Ignition
	// and satellites live in the checklist above, so they are not repeated here.
	const tile = (label, value, unit) => `
		<div style="flex:1 1 90px;min-width:90px;padding:8px 10px;border:1px solid var(--border-color);
					border-radius:var(--border-radius-md);background:var(--fg-color)">
			<div style="font-size:10px;letter-spacing:.6px;text-transform:uppercase;color:var(--text-muted)">${label}</div>
			<div style="font-size:20px;font-weight:600;line-height:1.25;margin-top:2px">${value}<span
				style="font-size:11px;font-weight:400;color:var(--text-muted);margin-left:3px">${unit || ""}</span></div>
		</div>`;

	const kpis = [
		tile(__("Speed"), st.speed === null || st.speed === undefined ? "&mdash;" : esc(st.speed), "km/h"),
		tile(__("Heading"), compass ? esc(compass) : "&mdash;",
			Number.isFinite(Number(st.direction)) ? esc(st.direction) + "°" : ""),
		tile(__("Altitude"), st.altitude === null || st.altitude === undefined ? "&mdash;" : esc(st.altitude), "m"),
		tile(__("Odometer"), dev.current_mileage === null || dev.current_mileage === undefined
			? "&mdash;" : esc(dev.current_mileage), "km"),
		tile(__("Parked"), esc(pilot2_duration(st.parking)), ""),
	].join("");

	// A calm rule instead of a heavy heading: the eye finds the section without
	// the label competing with the data underneath it.
	const section = (title, extra) =>
		`<div style="display:flex;align-items:center;gap:10px;margin:22px 0 10px">
			<span style="font-size:11px;letter-spacing:.6px;text-transform:uppercase;
						 color:var(--text-muted);font-weight:600;white-space:nowrap">${title}</span>
			${extra ? `<span style="font-size:11px;color:var(--text-muted);white-space:nowrap">${extra}</span>` : ""}
			<span style="flex:1;height:1px;background:var(--border-color)"></span>
		</div>`;

	// One airy label-over-value cell. Used in a wrapping flex row, this reads
	// far faster than a bordered table for a handful of identity fields.
	const field = (label, value) => `
		<div style="flex:1 1 145px;min-width:145px">
			<div style="font-size:10px;letter-spacing:.5px;text-transform:uppercase;
						color:var(--text-muted)">${label}</div>
			<div style="margin-top:2px;word-break:break-word">${value}</div>
		</div>`;

	// One sensor reading. `secondary` is used by paired probes (temp / humidity)
	// so a probe stays a single object on screen rather than two loose numbers.
	const reading_tile = (name, primary, secondary, foot) => `
		<div style="flex:1 1 148px;min-width:148px;padding:9px 11px;border:1px solid var(--border-color);
					border-radius:var(--border-radius-md);background:var(--fg-color)">
			<div style="font-size:10px;letter-spacing:.5px;text-transform:uppercase;color:var(--text-muted);
						white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${name}</div>
			<div style="font-size:18px;font-weight:600;line-height:1.3;margin-top:2px">
				${primary}${
					secondary
						? `<span style="font-size:13px;font-weight:400;color:var(--text-muted)"> / ${secondary}</span>`
						: ""
				}
			</div>
			${foot ? `<div style="font-size:10px;color:var(--text-muted);margin-top:1px">${foot}</div>` : ""}
		</div>`;

	const kv = (rows) =>
		`<table class="table table-borderless" style="margin:0;font-size:12px">${rows
			.filter((r) => r)
			.map(
				([k, v]) =>
					`<tr><td style="width:42%;padding:3px 0;color:var(--text-muted)">${k}</td>
					     <td style="padding:3px 0;word-break:break-word">${v}</td></tr>`
			)
			.join("")}</table>`;

	// ---- sensor readings (quick view) --------------------------------------
	// Every reading Pilot sent, as one scannable grid. Paired probes render as
	// a single tile carrying both values, so nothing appears twice.
	const now_ep = diag.server_epoch || Math.floor(Date.now() / 1000);

	const probe_tiles = (d.probes || []).map((p) => {
		const t = p.temperature || {};
		const h = p.humidity || {};
		const ts = Math.max(t.ts || 0, h.ts || 0);
		return reading_tile(
			pilot2_esc(p.label),
			t.display ? esc(t.display) : "&mdash;",
			h.display ? esc(h.display) : "&mdash;",
			(p.group ? esc(p.group) + " · " : "") +
				__("temp / humidity") +
				(ts ? " · " + esc(pilot2_ago(now_ep - ts)) : "")
		);
	});

	const other_tiles = (d.others || []).map((o) =>
		reading_tile(
			esc(o.name),
			o.display ? esc(o.display) : o.value !== null && o.value !== undefined ? esc(o.value) : "&mdash;",
			null,
			o.ts ? esc(pilot2_ago(now_ep - o.ts)) : ""
		)
	);

	const readings = probe_tiles.concat(other_tiles).join("");

	// ---- device identity (quick view) --------------------------------------
	const device_fields = [
		field(__("IMEI"), `<span style="font-family:monospace">${dash(dev.imei)}</span>`),
		field(__("Vehicle No."), dash(dev.name)),
		field(__("Model"), dash(dev.model)),
		field(__("Type"), dash(dev.type)),
		field(__("Folder"), dash(dev.folder)),
		field(__("Driver"), dash(dev.driver_name)),
		field(
			__("Odometer"),
			dev.current_mileage === null || dev.current_mileage === undefined
				? "&mdash;"
				: esc(dev.current_mileage) + " km"
		),
		field(__("Agent ID"), dash(dev.agentid)),
		dev.created_time ? field(__("Registered"), esc(pilot2_epoch_text(dev.created_time))) : "",
	].join("");

	// ---- ESSENTIAL VIEW ----------------------------------------------------
	const essential = `
		<div style="display:flex;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;gap:8px">
			<div>
				<div style="font-size:17px;font-weight:600">
					${dash(dev.name || info.license_plate)}
					<span class="indicator-pill ${is_stale ? "orange" : "green"}" style="margin-left:6px">
						${is_stale ? __("STALE") : __("LIVE")} · ${esc(pilot2_ago(age))}
					</span>
				</div>
				<div style="font-size:12px;color:var(--text-muted);margin-top:3px">
					${__("IMEI")}
					<span style="font-family:monospace;font-size:13px;color:var(--text-color)">${dash(dev.imei)}</span>
					<button class="btn btn-xs btn-default pilot2-copy-imei" style="padding:0 5px;margin-left:4px">${__("Copy")}</button>
					&nbsp;·&nbsp; ${dash(info.customer)}
					${info.license_plate ? "&nbsp;·&nbsp; " + dash(info.license_plate) : ""}
				</div>
			</div>
			<div class="text-muted" style="font-size:11px;text-align:right">
				${__("via")} ${dash(d.account)}<br>${__("node")} ${dash(d.node)}
			</div>
		</div>

		${section(__("Installation Checks"))}
		<table style="width:100%;font-size:12px;border-collapse:collapse">${checks.join("")}</table>

		${section(__("Status"))}
		<div style="display:flex;gap:8px;flex-wrap:wrap">${kpis}</div>

		${section(
			__("Sensor Readings"),
			d.probe_naming === "keyword" ? __("probes paired by name") : ""
		)}
		${
			readings
				? `<div style="display:flex;gap:8px;flex-wrap:wrap">${readings}</div>`
				: `<div class="text-muted">${__("No sensors reported")}</div>`
		}

		${section(__("Device"))}
		<div style="display:flex;gap:14px 18px;flex-wrap:wrap;font-size:12px">${device_fields}</div>

		${section(__("Location"), has_fix ? __("source") + ": " + esc(loc.source) : "")}
		${
			has_fix
				? `<div id="${map_id}" style="height:320px;border:1px solid var(--border-color);
							border-radius:var(--border-radius-md);overflow:hidden;background:var(--control-bg)"></div>
					<div style="margin-top:8px;display:flex;gap:6px;flex-wrap:wrap">
						<a class="btn btn-xs btn-default" target="_blank" rel="noopener noreferrer"
						   href="https://www.google.com/maps?q=${encodeURIComponent(loc.lat + "," + loc.lon)}">
							${__("Google Maps")}</a>
						<a class="btn btn-xs btn-default" target="_blank" rel="noopener noreferrer"
						   href="https://www.openstreetmap.org/?mlat=${encodeURIComponent(loc.lat)}&mlon=${encodeURIComponent(loc.lon)}#map=16/${encodeURIComponent(loc.lat)}/${encodeURIComponent(loc.lon)}">
							${__("OpenStreetMap")}</a>
						<button class="btn btn-xs btn-default pilot2-copy-coords">${__("Copy Coordinates")}</button>
					</div>`
				: `<div class="text-muted">${__("No GPS fix reported")}</div>`
		}`;

	// ---- FULL DETAIL (behind "Show all") -----------------------------------
	const probes = (d.probes || [])
		.map((p) => {
			const t = p.temperature || {};
			const h = p.humidity || {};
			return `<tr>
				<td>${dash(p.index)}</td><td>${dash(p.label)}</td>
				<td><b>${dash(t.display)}</b></td><td><b>${dash(h.display)}</b></td>
				<td class="text-muted">${dash(p.group)}</td>
			</tr>`;
		})
		.join("");

	const now_epoch = diag.server_epoch || Math.floor(Date.now() / 1000);
	const others = (d.others || [])
		.map(
			(o) => `<tr>
				<td>${dash(o.name)}</td><td><b>${dash(o.display)}</b></td>
				<td class="text-muted">${o.value === null || o.value === undefined ? "&mdash;" : esc(o.value)}</td>
				<td class="text-muted">${dash(o.raw_value)}</td>
				<td class="text-muted">${o.ts ? esc(pilot2_ago(now_epoch - o.ts)) : "&mdash;"}</td>
			</tr>`
		)
		.join("");

	const naming_note =
		d.probe_naming === "keyword"
			? `<div class="text-muted" style="font-size:11px;margin-bottom:6px">${__(
					"Paired by sensor name — this account does not use (T1)/(H1) probe labels."
			  )}</div>`
			: "";

	const rejected_html = (diag.rejected || []).length
		? `<div style="margin-top:6px"><div style="color:var(--text-muted)">${__(
				"Rejected accounts"
		  )}</div><ul style="margin:4px 0 0 16px;padding:0">${(diag.rejected || [])
				.map((r) => `<li style="margin-bottom:2px">${esc(r)}</li>`)
				.join("")}</ul></div>`
		: "";

	const details = `
		<div class="row">
			<div class="col-sm-6">
				${section(__("Device"))}
				${kv([
					[__("IMEI"), dash(dev.imei)],
					[__("Vehicle No."), dash(dev.name)],
					[__("Folder"), dash(dev.folder)],
					[__("Type"), dash(dev.type)],
					[__("Model"), dash(dev.model)],
					[__("Configuration"), dash(dev.configuration)],
					[__("Agent ID"), dash(dev.agentid)],
					[__("Unique ID"), dash(dev.uniqid)],
					dev.vin ? [__("VIN"), dash(dev.vin)] : null,
					[__("Driver"), dash(dev.driver_name)],
					dev.driver_phone ? [__("Driver Phone"), dash(dev.driver_phone)] : null,
					[__("Odometer"), dev.current_mileage === null || dev.current_mileage === undefined
						? "&mdash;" : esc(dev.current_mileage) + " km"],
					[__("Initial Mileage"), dev.initial_mileage === null || dev.initial_mileage === undefined
						? "&mdash;" : esc(dev.initial_mileage) + " km"],
					dev.created_time ? [__("Registered"), esc(pilot2_epoch_text(dev.created_time))] : null,
					dev.info ? [__("Info"), dash(dev.info)] : null,
				])}
			</div>
			<div class="col-sm-6">
				${section(__("State"))}
				${kv([
