// ---------------------------------------------------------------- ignition test
//
// Proves the ACC wire actually works, without anyone phoning the technician.
//
// Reads the current state, asks for the OPPOSITE, then polls Pilot every 5s for
// up to 5 minutes. Flip observed -> pass. Nothing after 5 minutes -> FALSE.
//
// A disconnected ignition input reports a permanent, plausible-looking "OFF",
// which is why "the field has a value" is not evidence of anything. Only the
// transition is.

const PILOT2_IGN = { window_ms: 5 * 60 * 1000, poll_ms: 5000 };

// Pilot sends `firing` as 1, "1", or occasionally a word.
function pilot2_ign_bool(v) {
	if (v === null || v === undefined || v === "") return null;
	if (v === 1 || v === "1" || v === true) return true;
	if (v === 0 || v === "0" || v === false) return false;
	const s = String(v).trim().toLowerCase();
	if (["on", "true", "yes"].includes(s)) return true;
	if (["off", "false", "no"].includes(s)) return false;
	return null;
}

function pilot2_mmss(ms) {
	const s = Math.max(0, Math.ceil(ms / 1000));
	return Math.floor(s / 60) + ":" + String(s % 60).padStart(2, "0");
}

function pilot2_ignition_test(dlg, frm, d, helpers) {
	const $row = dlg.$body.find("#pilot2-check-ignition");
	const $status = $row.find(".pilot2-check-status");
	const $value = $row.find(".pilot2-check-value");
	const $action = $row.find(".pilot2-check-action");

	const start_state = pilot2_ign_bool((d.state || {}).ignition);
	if (start_state === null) {
		frappe.msgprint({
			title: __("Ignition"),
			message: __("This device does not report an ignition value, so it cannot be tested."),
			indicator: "orange",
		});
		return;
	}

	const want = !start_state;
	const want_word = want ? __("ON") : __("OFF");
	const from_word = start_state ? __("ON") : __("OFF");

	const started_at = Date.now();
	const deadline = started_at + PILOT2_IGN.window_ms;

	let ticks = 0;          // 1s UI ticks
	let polls = 0;          // completed Pilot reads
	let in_flight = false;
	let seen = start_state; // most recent value Pilot reported
	let timer = null;

	const stop = () => {
		if (timer) clearInterval(timer);
		timer = null;
		dlg.$wrapper.off("hidden.bs.modal", stop);
	};

	// Polling must not outlive the dialog, or it keeps hitting Pilot unseen.
	dlg.$wrapper.on("hidden.bs.modal", stop);

	const render = () => {
		const left = deadline - Date.now();
		const pct = Math.min(100, ((Date.now() - started_at) / PILOT2_IGN.window_ms) * 100);
		$value.html(`
			<div style="font-size:14px;font-weight:600;color:var(--text-color)">
				${__("Turn the ignition {0} now", [want_word])}
			</div>
			<div style="height:4px;border-radius:2px;background:var(--control-bg);margin:7px 0 5px;overflow:hidden">
				<div style="height:100%;width:${pct}%;background:var(--blue-500,#2490ef);transition:width .9s linear"></div>
			</div>
			<div style="font-size:11px;color:var(--text-muted)">
				${__("Watching Pilot")} · ${pilot2_mmss(left)} ${__("left")} ·
				${__("{0} checks", [polls])} ·
				${__("currently reading")} <b>${seen === null ? "?" : seen ? __("ON") : __("OFF")}</b>
			</div>`);
		$action.html(
			`<button class="btn btn-xs btn-default pilot2-ign-stop">${__("Stop")}</button>`
		);
		$action.find(".pilot2-ign-stop").on("click", () => {
			stop();
			finish(null);
		});
	};

	// result: true = flipped, false = timed out, null = cancelled
	const finish = (result) => {
		stop();
		const secs = Math.round((Date.now() - started_at) / 1000);

		if (result === true) {
			$status.html(helpers.chip("ok"));
			$value.html(
				`<b style="color:var(--green-600,#16794c)">${__("TRUE")} — ${__(
					"ignition follows the key"
				)}</b>
				 <div style="font-size:11px;color:var(--text-muted);margin-top:2px">
					${__("Changed {0} → {1} after {2}s ({3} checks). The ACC wire is working.",
						[from_word, want_word, secs, polls])}
				 </div>`
			);
		} else if (result === false) {
			$status.html(helpers.chip("bad"));
			$value.html(
				`<b style="color:var(--red-600,#c0341d)">${__("FALSE")} — ${__(
					"ignition did not change"
				)}</b>
				 <div style="font-size:11px;color:var(--text-muted);margin-top:2px">
					${__("Still {0} after {1} and {2} checks.", [from_word, pilot2_mmss(PILOT2_IGN.window_ms), polls])}
					${__("Check the ACC wire, the fuse, and that the key was actually turned.")}
				 </div>`
			);
		} else {
			$status.html(helpers.chip("warn"));
			$value.html(
				`<b>${__("Test stopped")}</b>
				 <div style="font-size:11px;color:var(--text-muted);margin-top:2px">
					${__("Stopped after {0}s and {1} checks — result unknown.", [secs, polls])}
				 </div>`
			);
		}

		$action.html(`<button class="btn btn-xs btn-default pilot2-ign-test">${__("Check Again")}</button>`);
		$action.find(".pilot2-ign-test").on("click", () => pilot2_ignition_test(dlg, frm, d, helpers));
	};

	const poll = () => {
		// Never stack requests: if Pilot is slow, skip this slot rather than
		// queueing calls that all land at once.
		if (in_flight) return;
		in_flight = true;

		frappe.call({
			method: "app_apis.connector.get_snapshot",
			args: { ticket: frm.doc.name, account: 2 },
			// No freeze: the dialog must stay readable while this runs.
			callback(r) {
				in_flight = false;
				polls++;
				const msg = r && r.message;
				if (!msg) return;

				const cur = pilot2_ign_bool((msg.state || {}).ignition);
				if (cur !== null) seen = cur;

				if (cur === want) {
					finish(true);
					return;
				}
				render();
			},
			error() {
				// A single failed read should not abort a 5-minute test.
				in_flight = false;
				polls++;
			},
		});
	};

	render();
	poll(); // read immediately so the first result is not 5s away

	timer = setInterval(() => {
		ticks++;
		if (Date.now() >= deadline) {
			finish(false);
			return;
		}
		render();
		if (ticks % (PILOT2_IGN.poll_ms / 1000) === 0) poll();
	}, 1000);
}

// ---------------------------------------------------------------- map

function pilot2_render_map(map_id, d) {
	const loc = d.location || {};
	const st = d.state || {};
	const dev = d.device || {};

	// Runs more than once on purpose (see the scheduling at the bottom): the
	// _leaflet_id guard makes every call after the first a no-op.
	const init = () => {
		const el = document.getElementById(map_id);
		if (!el || el._leaflet_id) return;

		try {
			pilot2_build_map(el, map_id, loc, st, dev);
		} catch (e) {
			// Never leave an unexplained grey rectangle: say what went wrong
			// and still give the reader a way to see the position.
			console.error("[pilot] map failed to render", e);
			el.innerHTML =
				`<div class="text-muted" style="padding:16px">
					${__("Map could not be drawn")}: ${frappe.utils.escape_html(String(e.message || e))}.
					<a target="_blank" rel="noopener noreferrer"
					   href="https://www.openstreetmap.org/?mlat=${encodeURIComponent(loc.lat)}&mlon=${encodeURIComponent(loc.lon)}">
					   ${__("Open map")}</a>
				 </div>`;
		}
	};

	// A Leaflet map sizes itself from its container, and the container has no
	// layout until the modal's fade-in finishes -- initialising too early
	// yields a 0x0 map and a grey box. Hook the modal's own "shown" event and
	// keep two timed retries as a fallback for when that event is missed.
	$(document).one("shown.bs.modal", init);
	setTimeout(init, 150);
	setTimeout(init, 700);
}

function pilot2_build_map(el, map_id, loc, st, dev) {
	if (typeof L === "undefined" || !L.map) {
		throw new Error(__("Leaflet is not loaded"));
	}

	const defaults = (frappe.utils.map_defaults || {}).tiles || {};
	const map = L.map(map_id, { scrollWheelZoom: false }).setView([loc.lat, loc.lon], 15);

	const street = L.tileLayer(
		(defaults.default_tile || {}).url || "https://tile.openstreetmap.org/{z}/{x}/{y}.png",
		(defaults.default_tile || {}).options || {}
	);
	const satellite = defaults.satellite_tile
		? L.tileLayer(defaults.satellite_tile.url, defaults.satellite_tile.options)
		: null;

	street.addTo(map);
	if (satellite) {
		L.control.layers({ [__("Street")]: street, [__("Satellite")]: satellite }, {}).addTo(map);
	}

	// A divIcon rather than the default PNG marker: frappe's bundled marker
	// images are named "leafletmarker-icon.png", which does not match the
	// "marker-icon.png" Leaflet derives from imagePath, so the stock icon
	// 404s. Drawing the marker in CSS also lets it carry the heading.
	const heading = Number(st.direction);
	const arrow = Number.isFinite(heading)
		? `<div style="position:absolute;left:50%;top:50%;width:0;height:0;
					transform:translate(-50%,-50%) rotate(${heading}deg)">
				<div style="position:absolute;left:-6px;top:-24px;width:0;height:0;
							border-left:6px solid transparent;border-right:6px solid transparent;
							border-bottom:10px solid #2490ef"></div>
		   </div>`
		: "";

	const icon = L.divIcon({
		className: "",
		iconSize: [22, 22],
		iconAnchor: [11, 11],
		html: `<div style="position:relative;width:22px;height:22px">
				${arrow}
				<div style="position:absolute;inset:0;border-radius:50%;background:#2490ef;
							border:2px solid #fff;box-shadow:0 0 0 1px rgba(0,0,0,.25)"></div>
			   </div>`,
	});

	const popup = [
		`<b>${pilot2_esc(dev.name || dev.imei)}</b>`,
		`${__("Speed")}: ${pilot2_esc(st.speed)} km/h`,
		`${__("Ignition")}: ${st.ignition === 1 || st.ignition === "1" ? __("ON") : __("OFF")}`,
		`${loc.lat}, ${loc.lon}`,
	].join("<br>");

	L.marker([loc.lat, loc.lon], { icon }).addTo(map).bindPopup(popup);

	// Accuracy is not reported, so draw nothing implying it. A light circle
	// only marks the point at low zoom.
	L.circle([loc.lat, loc.lon], {
		radius: 40,
		color: "#2490ef",
		weight: 1,
		opacity: 0.5,
		fillOpacity: 0.08,
	}).addTo(map);

	// The container may still have been mid-animation when this ran.
	map.invalidateSize();
	setTimeout(() => map.invalidateSize(), 300);
}

// =============================================================================
// customer-vehicle-wasl  --  Client Script (dt = Customer Vehicle, view = Form)
// =============================================================================
// "Check WASL" and "Link to WASL" in the dropdown of every Pilot connection that
// has Uses WASL ticked (app_apis > Pilot Connections; the dropdown itself is made
// by customer-vehicle-upload). Link opens a dialog laid out like
// Pilot's own WASL vehicle form (Vehicle Plate / Tracking Device / Sensors /
// Weight Sensor Calibration), pre-filled from this record by the Server Script
// "wasl_link_api" (action=plan). Weight calibration and the SIM provider come
// in as static defaults and can be changed before linking.
// "Link to WASL" sends the confirmed form back, through that connection.
// =============================================================================

(function () {
  var METHOD = "wasl_link_api";
  var APP_METHOD = "app_apis.wasl.link_vehicle";   // custom app: app_apis/app_apis/wasl.py

  var PLATE_TYPES = [
    ["1", "Private Car"], ["2", "Public Transport"], ["3", "Private Transport"],
    ["4", "Public Minibus"], ["5", "Private Minibus"], ["6", "Taxi"],
    ["7", "Heavy Equipment"], ["8", "Export"], ["9", "Diplomatic"],
    ["10", "Motorcycle"], ["11", "Temporary"]
  ];
  var TELECOMS = ["BEYOND ONE", "BULL", "eSIM", "FREEDOM", "GO", "LEBARA",
                  "MOBILY", "RED", "SALAM", "STC", "ZAIN"];
  var SOURCES = [["RS", "Standard"], ["ONE_WIRE", "One Wire"], ["BLUETOOTH", "Bluetooth"]];
  var WEIGHT_SOURCES = [["ANALOG", "Analog"], ["CAN", "CAN Bus"]];

  // Frappe Select options keep the label; we map label <-> id ourselves.
  function labels(pairs) { return pairs.map(function (p) { return p[1]; }).join("\n"); }
  function label_of(pairs, id) {
    for (var i = 0; i < pairs.length; i++) if (String(pairs[i][0]) === String(id)) return pairs[i][1];
    return "";
  }
  function id_of(pairs, label) {
    for (var i = 0; i < pairs.length; i++) if (pairs[i][1] === label) return pairs[i][0];
    return "";
  }

  // Weight calibration rows: a narrow label column on the left, like Pilot's form.
  var WEIGHT_ROWS = ["wrow_source", "wrow_empty", "wrow_half", "wrow_full"];
  function row_label(text) {
    return '<div class="wasl-row-label" style="padding-top:26px;font-weight:500;color:var(--text-color)">' +
      frappe.utils.escape_html(text) + "</div>";
  }
  function layout_weight_rows(d) {
    var wide = window.matchMedia("(min-width: 576px)").matches;
    WEIGHT_ROWS.forEach(function (fn, i) {
      var col = d.fields_dict[fn].$wrapper.closest(".form-column");
      var sec = col.closest(".form-section");
      if (wide) {
        col.css({ flex: "0 0 16%", "max-width": "16%" });
        col.siblings(".form-column").css({ flex: "1 1 0", "max-width": "none" });
      }
      if (i > 0) sec.css({ "padding-top": 0 });
      if (i < WEIGHT_ROWS.length - 1) sec.css({ "padding-bottom": 0 });
    });
  }

  function may_use() {
    return frappe.session.user !== "Guest";
  }

  // The Pilot connections, read once per page load (shared with customer-vehicle-upload).
  function with_connections(done) {
    if (window.cvu_connections) { done(window.cvu_connections); return; }
    frappe.call({
      method: "app_apis.pilot_admin.connections",
      callback: function (r) { window.cvu_connections = (r && r.message) || []; done(window.cvu_connections); },
      error: function () { done([]); }
    });
  }

  function call(frm, con, action, extra, done) {
    var a = { action: action, vehicle: frm.doc.name, connection: con.key };
    Object.keys(extra || {}).forEach(function (k) { a[k] = extra[k]; });
    frappe.call({
      method: METHOD, args: a, freeze: true,
      freeze_message: action === "plan" ? __("Loading WASL form...") : __("Linking with WASL..."),
      callback: function (r) {
        var res = r && r.message ? r.message : null;
        if (!res) { frappe.msgprint(__("Empty response.")); return; }
        if (res.error) { frappe.msgprint({ title: __("WASL"), indicator: "red", message: frappe.utils.escape_html(res.error) }); return; }
        done(res);
      }
    });
  }

  function open_dialog(frm, con, f) {
    var d = new frappe.ui.Dialog({
      title: "WASL · " + con.label + " · " + [f.plate_number, f.left_letter, f.middle_letter, f.right_letter].filter(Boolean).join(" "),
      size: "extra-large",
      fields: [
        // ---------------- Vehicle Plate | Tracking Device
        { fieldtype: "Section Break", label: __("Vehicle Plate") },
        { fieldtype: "Select", fieldname: "plate_type", label: __("Plate Type"), reqd: 1,
          options: labels(PLATE_TYPES), default: label_of(PLATE_TYPES, f.plateType) },
        { fieldtype: "Data", fieldname: "plate_number", label: __("Plate Number"), reqd: 1, default: f.plate_number },
        { fieldtype: "Data", fieldname: "sequenceNumber", label: __("Sequence Number"), reqd: 1, default: f.sequenceNumber },
        { fieldtype: "Column Break" },
        { fieldtype: "Data", fieldname: "left_letter", label: __("Left Letter"), reqd: 1, default: f.left_letter },
        { fieldtype: "Data", fieldname: "middle_letter", label: __("Middle Letter"), reqd: 1, default: f.middle_letter },
        { fieldtype: "Data", fieldname: "right_letter", label: __("Right Letter"), reqd: 1, default: f.right_letter },
        { fieldtype: "Data", fieldname: "imeiNumber", label: __("Imei Number"), reqd: 1, default: f.imeiNumber },
        { fieldtype: "Column Break", label: __("Tracking Device") },
        { fieldtype: "Select", fieldname: "telecomCompanyName", label: __("Telecom service provider"), reqd: 1,
          options: TELECOMS.join("\n"), default: f.telecomCompanyName },
        { fieldtype: "Data", fieldname: "deviceBrand", label: __("Tracking device Brand"), reqd: 1, default: f.deviceBrand },
        { fieldtype: "Column Break" },
        { fieldtype: "Data", fieldname: "simNumber", label: __("Data SIM number"), reqd: 1, default: f.simNumber,
          description: __("966XXXXXXXXX") },
        { fieldtype: "Data", fieldname: "deviceModel", label: __("Tracking device Model"), reqd: 1, default: f.deviceModel },

        // ---------------- Sensors
        { fieldtype: "Section Break", label: __("Sensors") },
        { fieldtype: "Check", fieldname: "hasTemperatureSensor", label: __("Has temperature sensor"), default: f.hasTemperatureSensor },
        { fieldtype: "Select", fieldname: "temperatureSource", label: __("Temperature source"),
          options: "\n" + labels(SOURCES), depends_on: "eval:doc.hasTemperatureSensor",
          mandatory_depends_on: "eval:doc.hasTemperatureSensor" },
        { fieldtype: "Column Break" },
        { fieldtype: "Check", fieldname: "hasHumiditySensor", label: __("Has humidity sensor"), default: f.hasHumiditySensor },
        { fieldtype: "Select", fieldname: "humiditySource", label: __("Humidity source"),
          options: "\n" + labels(SOURCES), depends_on: "eval:doc.hasHumiditySensor",
          mandatory_depends_on: "eval:doc.hasHumiditySensor" },

        // ---------------- Weight Sensor Calibration (static defaults)
        // Laid out like Pilot's own form: a row label on the left, Weight (kg) | Voltage (mV) on the right.
        { fieldtype: "Section Break", label: __("Weight Sensor Calibration") },
        { fieldtype: "HTML", fieldname: "wrow_source", options: row_label(__("Weight source")) },
        { fieldtype: "Column Break" },
        { fieldtype: "Select", fieldname: "weightSource", label: __("Weight source"), reqd: 1,
          options: labels(WEIGHT_SOURCES), default: label_of(WEIGHT_SOURCES, f.weightSource) },
        { fieldtype: "Column Break" },
        { fieldtype: "Select", fieldname: "weightSensorAnalogNumber", label: __("Weight Sensor Channel"),
          options: "1\n2\n3\n4", default: String(f.weightSensorAnalogNumber || "1"),
          depends_on: "eval:doc.weightSource=='Analog'", mandatory_depends_on: "eval:doc.weightSource=='Analog'" },

        { fieldtype: "Section Break", hide_border: 1 },
        { fieldtype: "HTML", fieldname: "wrow_empty", options: row_label(__("Empty")) },
        { fieldtype: "Column Break" },
        { fieldtype: "Int", fieldname: "weightInKilogramsEmptyVehicle", label: __("Weight (kg)"), reqd: 1, default: f.weightInKilogramsEmptyVehicle },
        { fieldtype: "Column Break" },
        { fieldtype: "Int", fieldname: "mlVoltageEmptyVehicle", label: __("Voltage (mV)"), reqd: 1, default: f.mlVoltageEmptyVehicle },

        { fieldtype: "Section Break", hide_border: 1 },
        { fieldtype: "HTML", fieldname: "wrow_half", options: row_label(__("Half")) },
        { fieldtype: "Column Break" },
        { fieldtype: "Int", fieldname: "weightInKilogramsHalfLoad", label: __("Weight (kg)"),
          default: f.weightInKilogramsHalfLoad == null ? "" : String(f.weightInKilogramsHalfLoad) },
        { fieldtype: "Column Break" },
        { fieldtype: "Data", fieldname: "mlVoltageHalfLoad", label: __("Voltage (mV)"), default: f.mlVoltageHalfLoad },

        { fieldtype: "Section Break", hide_border: 1 },
        { fieldtype: "HTML", fieldname: "wrow_full", options: row_label(__("Full")) },
        { fieldtype: "Column Break" },
        { fieldtype: "Int", fieldname: "weightInKilogramsFullLoad", label: __("Weight (kg)"), reqd: 1, default: f.weightInKilogramsFullLoad },
        { fieldtype: "Column Break" },
        { fieldtype: "Int", fieldname: "mlVoltageFullLoad", label: __("Voltage (mV)"), reqd: 1, default: f.mlVoltageFullLoad }
      ],
      primary_action_label: __("Link to WASL"),
      primary_action: function (v) {
        var sim = String(v.simNumber || "").replace(/\s/g, "");
        if (!/^966\d{1,15}$/.test(sim)) {
          frappe.msgprint(__("SIM Number must start with 966 and contain digits only."));
          return;
        }
        var form = {
          plateType: id_of(PLATE_TYPES, v.plate_type),
          plate_number: v.plate_number, left_letter: v.left_letter,
          middle_letter: v.middle_letter, right_letter: v.right_letter,
          sequenceNumber: v.sequenceNumber, imeiNumber: v.imeiNumber,
          telecomCompanyName: v.telecomCompanyName, simNumber: sim,
          deviceBrand: v.deviceBrand, deviceModel: v.deviceModel,
          hasTemperatureSensor: v.hasTemperatureSensor ? 1 : 0,
          temperatureSource: id_of(SOURCES, v.temperatureSource),
          hasHumiditySensor: v.hasHumiditySensor ? 1 : 0,
          humiditySource: id_of(SOURCES, v.humiditySource),
          weightSource: id_of(WEIGHT_SOURCES, v.weightSource),
          weightSensorAnalogNumber: v.weightSensorAnalogNumber,
          weightInKilogramsEmptyVehicle: v.weightInKilogramsEmptyVehicle,
          mlVoltageEmptyVehicle: v.mlVoltageEmptyVehicle,
          weightInKilogramsHalfLoad: v.weightInKilogramsHalfLoad,
          mlVoltageHalfLoad: v.mlVoltageHalfLoad,
          weightInKilogramsFullLoad: v.weightInKilogramsFullLoad,
          mlVoltageFullLoad: v.mlVoltageFullLoad
        };
        var esc = frappe.utils.escape_html;
        var plate = [form.plate_number, form.left_letter, form.middle_letter, form.right_letter].join(" ");
        // Always ask before anything goes to Pilot / WASL.
        frappe.confirm(
          "<b>" + __("Send this vehicle to WASL?") + "</b><br><br>" +
          __("Vehicle") + ": " + esc(frm.doc.name) + "<br>" +
          __("Plate") + ": " + esc(plate) + "<br>" +
          __("IMEI") + ": " + esc(form.imeiNumber) + "<br>" +
          __("SIM") + ": " + esc(form.telecomCompanyName) + " " + esc(form.simNumber) + "<br>" +
          __("Device") + ": " + esc(form.deviceModel) + "<br>" +
          __("Through") + ": " + esc(con.label) + "<br><br>" +
          __("This saves the WASL form on Pilot and registers the vehicle with WASL."),
          function () {
            frappe.call({
              method: APP_METHOD,
              args: { vehicle: frm.doc.name, form: JSON.stringify(form), register: 1, account: con.account },
              freeze: true, freeze_message: __("Registering with WASL... (can take a minute)"),
              callback: function (r) {
                var res = (r && r.message) || {};
                frappe.msgprint({
                  title: res.ok ? __("Linked with WASL") : __("Not linked"),
                  indicator: res.ok ? "green" : "red",
                  message: esc(res.msg || "") + (res.step ? '<br><span class="text-muted small">' +
                    __("Step") + ": " + esc(res.step) + "</span>" : "")
                });
                if (res.ok) { d.hide(); check_status(frm, con, false); }
              },
              error: function () {
                frappe.msgprint({ title: __("Not linked"), indicator: "red",
                  message: __("The WASL method did not run. If it says the method is not found, app_apis/wasl.py is not installed on the server yet.") });
              }
            });
          });
      }
    });
    d.show();
    layout_weight_rows(d);
  }

  // ---------------------------------------------------------------- status
  var STATES = {
    linked:               ["green",  __("Linked with WASL")],
    registered_inactive:  ["orange", __("Registered in WASL, but not active")],
    saved_not_registered: ["orange", __("WASL form saved on Pilot, not registered")],
    not_linked:           ["red",    __("Not linked with WASL")],
    not_on_pilot:         ["red",    __("Not on Pilot (IMEI not found)")],
    unknown:              ["gray",   __("WASL status unknown")]
  };

  function show_status(frm, con, st, popup) {
    var s = STATES[st.state] || STATES.unknown;
    var esc = frappe.utils.escape_html;
    var when = st.ts ? frappe.datetime.str_to_user(frappe.datetime.convert_to_user_tz(
      moment.unix(parseInt(st.ts, 10)).utc().format("YYYY-MM-DD HH:mm:ss"))) : "";
    var line = '<span class="indicator-pill ' + s[0] + '">' + esc(s[1]) + "</span>" +
      (st.referencekey ? ' <span class="text-muted small">' + __("Ref") + ": " + esc(st.referencekey) + "</span>" : "") +
      (when ? ' <span class="text-muted small">· ' + esc(when) + "</span>" : "");
    frm.dashboard.set_headline_alert(line);
    if (!popup) return;
    var rows = [
      [__("Status"), '<span class="indicator-pill ' + s[0] + '">' + esc(s[1]) + "</span>"],
      [__("IMEI"), esc(st.imei || "")],
      [__("Pilot vehicle"), esc(st.pilot_name || "")],
      [__("Pilot agent id"), esc(st.agent_id || "")],
      [__("WASL reference key"), esc(st.referencekey || "—")],
      [__("WASL status code"), esc(st.wasl_status || "—")],
      [__("Last WASL update"), esc(when || "—")]
    ];
    if (st.detail) rows.push([__("Note"), esc(st.detail)]);
    frappe.msgprint({
      title: __("WASL status") + " · " + con.label, indicator: s[0],
      message: '<table class="table table-bordered" style="margin:0">' + rows.map(function (r) {
        return '<tr><td class="text-muted" style="width:40%">' + r[0] + "</td><td>" + r[1] + "</td></tr>";
      }).join("") + "</table>"
    });
  }

  function check_status(frm, con, popup) {
    frappe.call({
      method: METHOD, args: { action: "status", vehicle: frm.doc.name, connection: con.key },
      freeze: !!popup, freeze_message: __("Checking WASL..."),
      callback: function (r) {
        var res = r && r.message ? r.message : {};
        if (res.error) { if (popup) frappe.msgprint(frappe.utils.escape_html(res.error)); return; }
        show_status(frm, con, res.status || {}, popup);
      }
    });
  }

  // ---------------------------------------------------------------- wiring
  frappe.ui.form.on("Customer Vehicle", {
    refresh: function (frm) {
      if (frm.is_new() || !may_use()) return;
      with_connections(function (cons) {
        cons.filter(function (c) { return c.uses_wasl; }).forEach(function (con) {
          var group = con.label;   // the connection's own dropdown (customer-vehicle-upload)
          frm.add_custom_button(__("Check WASL"), function () { check_status(frm, con, true); }, group);
          frm.add_custom_button(__("Link to WASL"), function () {
            if (!String(frm.doc.device_serial || "").trim()) {
              frappe.msgprint({ title: __("No Device"), indicator: "red",
                message: __("This vehicle has no Device Serial (IMEI).") });
              return;
            }
            call(frm, con, "plan", {}, function (res) { open_dialog(frm, con, res.form || {}); });
          }, group);
        });
      });
      // The WASL status used to be fetched live from Pilot every time a vehicle was opened (about five
      // requests each). The Systems section at the top of the form now shows it from the hourly copy,
      // so nothing is queried on open; "Check WASL" still asks Pilot on demand.
    }
  });
})();

// =============================================================================
// customer-vehicle-upload  --  Client Script (dt = Customer Vehicle, view = Form)
// =============================================================================
//
// One BLACK dropdown in the form toolbar PER PILOT CONNECTION (the rows of
// app_apis > Pilot Connections), named after the connection, holding:
//   Upload · Edit · Check vehicle · Delete
//   and, when the connection has Uses WASL ticked:
//   Check WASL · Link to WASL (both from customer-vehicle-wasl) · Remove from WASL
// plus one per IM connection (app_apis > IM Connections: Upload · Check vehicle · Delete) and one for the SIM.
// The calls go to the Server Script `vehicle_upload_api`; the connection list
// comes from app_apis.pilot_admin.connections.
//
// The flow is deliberately two-step, because the person asked to be sure the
// right data goes out:
//
//   1. picking a target calls action=plan -- the server builds the payload from
//      the Customer Vehicle record and returns it WITHOUT sending anything.
//   Upload > Edit on Pilot changes a vehicle that is ALREADY on Pilot (plate, IMEI,
//   SIM, device type, vehicle type) and shows what Pilot holds empty for it.
//
//   2. the dialog shows that payload field by field. For Pilot the plate, IMEI,
//      SIM, device type, account email and VEHICLE TYPE are editable there
//      ("Re-check" rebuilds the payload with the changes). Only "Upload Now"
//      runs action=upload, and it sends the changes as `overrides`.
//
// While the Server Script has LIVE = 0 (its default) step 2 also sends nothing
// and says so, so the whole chain is safe to click through.
//
// On a real success the Server Script stamps this vehicle's Installation
// xticket: Server section -> Server status -> uploaded. On a refusal it writes
// duplicate / vehicle_not_found / failure instead, and the reason is shown here.
// =============================================================================

(function () {
    // ------------------------------------------------------------ button switches
    // 1 = visible, 0 = hidden. Change a value, save the Client Script, then
    // reload the Customer Vehicle form.

    // Items in each Pilot connection's dropdown
    var SHOW_UPLOAD = 1;          // <connection> > Upload
    var SHOW_EDIT = 1;            // <connection> > Edit -- change a vehicle already on Pilot
    var SHOW_CHECK_VEHICLE = 1;   // <connection> > Check vehicle (read-only)
    var SHOW_DELETE = 1;          // <connection> > Delete
    var SHOW_REMOVE_WASL = 1;     // <connection> > Remove from WASL (connections that use WASL)

    // The IM dropdowns (one per row of app_apis > IM Connections), and the extra Upload button
    var SHOW_IM = 1;              // <IM connection> > Upload / Check vehicle / Delete
    var SHOW_ALL_PLATFORMS = 1;   // "Upload to all" -- every platform the vehicle has an account on

    // Buttons in the payload dialog
    var SHOW_UPLOAD_NOW = 1;      // "Upload Now"
    var SHOW_VERIFY_STAMP = 1;    // "Verify & Stamp"

    // The SIM dropdown
    var SHOW_CHECK_SIM = 1;       // SIM > Check SIM (read-only, Lebara)
    var SHOW_SUSPEND_SIM = 1;     // SIM > Suspend SIM (Lebara)
    // ---------------------------------------------------------------------------

    var METHOD = "vehicle_upload_api";
    var SIM_GROUP = "SIM";
    var DELETE_WORD = "DELETE";

    // Each item: key (server target), label (card), title (dialog), word (typed to confirm),
    // done (success title), warn (what it does), busy (while it runs), connection (for WASL).
    function platform_delete(key, label) {
        return {
            key: key, label: label, word: DELETE_WORD,
            title: __("Delete from {0}", [label]), done: __("Deleted"), busy: __("Deleting from {0}...", [label]),
            warn: __("This cannot be undone. The vehicle and its stored data and sensors are removed from {0}. The ERP vehicle is not touched.", [label])
        };
    }
    function wasl_delete(con) {
        return {
            key: "wasl", connection: con.key, label: __("WASL through {0}", [con.label]), word: DELETE_WORD,
            title: __("Remove from WASL"), done: __("Removed from WASL"), busy: __("Removing from WASL..."),
            warn: __("Deletes the vehicle from the WASL database only, through {0}'s own WASL window. The Pilot vehicle stays. WASL may refuse if the vehicle is locked.", [con.label])
        };
    }
    var SIM_SUSPEND = {
        key: "sim", label: __("Suspend SIM"), word: "SUSPEND",
        title: __("Suspend SIM"), done: __("SIM suspended"), busy: __("Suspending the SIM..."),
        warn: __("Suspends this vehicle's SIM on Lebara (Lebara SIMs only). It can be resumed from Lebara. The vehicle itself is not touched.")
    };

    // The IM connections, read once per page load: [{account, key, label, enabled, email_fields}]
    function with_im_connections(done) {
        if (window.cvu_im_connections) { done(window.cvu_im_connections); return; }
        frappe.call({
            method: "app_apis.im_connector.connections",
            callback: function (r) { window.cvu_im_connections = (r && r.message) || []; done(window.cvu_im_connections); },
            error: function () { done([]); }
        });
    }

    // The Pilot connections, read once per page load: [{account, key, label, enabled, uses_wasl, email_fields}]
    function with_connections(done) {
        if (window.cvu_connections) { done(window.cvu_connections); return; }
        frappe.call({
            method: "app_apis.pilot_admin.connections",
            callback: function (r) { window.cvu_connections = (r && r.message) || []; done(window.cvu_connections); },
            error: function () { done([]); }
        });
    }

    // The payload keys worth showing, in the order a technician reads them.
    // These are the cmd=vehadd parameters, in the order Pilot documents them,
    // followed by the ERP values they were resolved FROM (the underscored keys).
    var SHOW = [
        ["vehiclenumber", __("vehiclenumber — on Pilot")],
        ["uniqid", __("uniqid (IMEI)")],
        ["configuration", __("configuration (device type)")],
        ["_type_name", __("vehicle type — set on Pilot after create")],
        ["_type_note", __("note on vehicle type")],
        ["account_name", __("account_name")],
        ["name", __("name — on Pilot")],
        ["imei", __("imei")],
        ["account_id", __("account_id")],
        ["vehmodel", __("vehmodel")],
        ["type", __("type")],
        ["msisdn", __("msisdn")],
        ["msisdn2", __("msisdn2")],
        ["folder", __("folder")],
        ["_folder_name", __("resolved from — root folder of the account")],
        ["node", __("node")],
        ["_account_email", __("resolved from — platform account")],
        ["_device_type", __("resolved from — device type")],
        ["_vehicle_type", __("resolved from — vehicle type")],
        ["_msisdn_note", __("note on msisdn")],
        ["_sensors", __("sensors to add")],
        ["_edited", __("changed in this dialog")],
        // IM (Trakzee) Add Vehicle form
        ["object_device_name", __("vehicle name — on IM")],
        ["object_imei_no", __("IMEI — on IM")],
        ["object_company_id", __("IM company id")],
        ["_reseller", __("IM reseller id")],
        ["object_location_id", __("IM branch id")],
        ["_im_company", __("IM company — found by")],
        ["object_gps_device_model_id", __("IM device model id")],
        ["object_sim_card_no", __("SIM number — on IM")],
        ["sim_provide", __("SIM provider id")]
    ];

    function may_upload() {
        return frappe.session.user !== "Guest";
    }

    var esc = frappe.utils.escape_html;

    // ---------------------------------------------------------------- styling
    // Frappe renders a button group as .inner-group-button[data-label] with the
    // toggle as its first button. Paint that one black. The CSS goes in once;
    // the JS pass is a fallback for builds that do not set data-label.
    function paint_black(frm, group) {
        paint_group(frm, group, "cv-upload-black", "#1b1d21", "#000");
    }

    // ---------------------------------------------------------------- dialog
    function payload_table(rows) {
        // A row is shown whenever the key EXISTS in the payload, even when the
        // value is empty -- an intentionally blank msisdn is information, not a
        // gap. The real errors are listed under the table, from `gaps`.
        var body = SHOW.map(function (pair) {
            var any = false;
            var cells = rows.map(function (r) {
                var p = r.payload || {};
                var v = p[pair[0]];
                if (pair[0] in p) any = true;
                // "0" is a genuine value for msisdn -- Pilot stores it for a
                // SIM-less vehicle. It only means "not resolved" on the ids.
                var zeroIsMissing = { account_id: 1, vehmodel: 1, type: 1 };
                var blank = (v === undefined || v === null || String(v) === "" ||
                    (String(v) === "0" && zeroIsMissing[pair[0]]));
                return '<td style="padding:4px 8px;border-top:1px solid var(--border-color)">' +
                    (blank
                        ? '<span style="color:var(--text-muted)">' + __("(empty)") + "</span>"
                        : esc(String(v))) + "</td>";
            }).join("");
            if (!any) return "";
            return '<tr><td style="padding:4px 8px;border-top:1px solid var(--border-color);' +
                'color:var(--text-muted);white-space:nowrap">' + esc(pair[1]) + "</td>" + cells + "</tr>";
        }).join("");

        var head = rows.map(function (r) {
            return '<th style="padding:4px 8px;text-align:left">' + esc(r.label) + "</th>";
        }).join("");

        return '<table style="width:100%;font-size:12px;border-collapse:collapse">' +
            '<thead><tr><th style="padding:4px 8px;text-align:left;color:var(--text-muted)">' +
            __("Field") + "</th>" + head + "</tr></thead><tbody>" + body + "</tbody></table>";
    }

    // ---------------------------------------------------------------- cards
    // Results are shown as one card per platform plus one for the ticket.
    // Colours come from Frappe's own CSS variables, so dark mode follows.
    function card_css() {
        if (document.getElementById("cvu-card-css")) return;
        var css = document.createElement("style");
        css.id = "cvu-card-css";
        css.textContent = [
            ".cvu-card{border:1px solid var(--border-color);border-radius:10px;background:var(--card-bg,var(--bg-color));",
            "  margin-top:10px;overflow:hidden;font-size:13px}",
            ".cvu-card-head{display:flex;align-items:center;gap:10px;padding:10px 14px;",
            "  border-bottom:1px solid var(--border-color)}",
            ".cvu-card-head .cvu-title{font-weight:600;flex:1}",
            ".cvu-dot{width:10px;height:10px;border-radius:50%;flex:none}",
            ".cvu-pill{font-size:11px;font-weight:600;padding:2px 10px;border-radius:999px;white-space:nowrap}",
            ".cvu-body{padding:10px 14px}",
            ".cvu-headline{font-weight:600;margin-bottom:6px}",
            ".cvu-row{display:flex;gap:12px;padding:5px 0;border-top:1px dashed var(--border-color)}",
            ".cvu-row:first-of-type{border-top:0}",
            ".cvu-key{color:var(--text-muted);min-width:110px;flex:none}",
            ".cvu-val{flex:1;word-break:break-word}",
            ".cvu-said{font-family:var(--font-family-monospace,monospace);font-size:11px;color:var(--text-muted)}",
            ".cvu-strip{margin-top:8px;padding:8px 12px;border-radius:8px;font-size:12px;border:1px solid}",
            ".cvu-gaps{margin:4px 0 0 18px;padding:0}",
            ".cvu-green{background:var(--green-100,#e4f5e9);color:var(--green-800,#14532d)}",
            ".cvu-red{background:var(--red-100,#fde8e8);color:var(--red-800,#7f1d1d)}",
            ".cvu-orange{background:var(--orange-100,#fdf0e1);color:var(--orange-800,#7c2d12)}",
            ".cvu-blue{background:var(--blue-100,#e3eefd);color:var(--blue-800,#1e3a8a)}",
            ".cvu-grey{background:var(--gray-100,#f1f1f3);color:var(--gray-700,#4b5563)}",
            ".cvu-dot.cvu-green{background:var(--green-500,#22c55e)}",
            ".cvu-dot.cvu-red{background:var(--red-500,#ef4444)}",
            ".cvu-dot.cvu-orange{background:var(--orange-500,#f59e0b)}",
            ".cvu-dot.cvu-blue{background:var(--blue-500,#3b82f6)}",
            ".cvu-dot.cvu-grey{background:var(--gray-400,#9ca3af)}",
            ".cvu-strip.cvu-blue{border-color:var(--blue-200,#bfd5fb)}",
            ".cvu-strip.cvu-orange{border-color:var(--orange-200,#f8d3a8)}",
            ".cvu-strip.cvu-grey{border-color:var(--border-color)}"
        ].join("\n");
        document.head.appendChild(css);
    }

    // verdict -> [tone, label]
    function status_of(r) {
        if (r.blocked) return ["grey", __("Not sent")];
        var v = r.verdict || "";
        if (v === "uploaded") return ["green", r.mode === "verify" ? __("Registered") : (r.mode === "edit" ? __("Saved") : __("Uploaded"))];
        if (r.mode === "edit" && r.ok && !v) return ["grey", __("No change")];
        if (v === "duplicate") return ["orange", __("Duplicate")];
        if (v === "vehicle_not_found") return ["red", __("Not found")];
        if (v === "failure") return ["red", __("Failed")];
        if (v === "error") return ["orange", __("Error")];
        if ((r.gaps || []).length) return ["red", __("Incomplete")];
        return ["blue", __("Ready")];
    }

    function row_html(key, val, raw) {
        return '<div class="cvu-row"><div class="cvu-key">' + esc(key) + '</div><div class="cvu-val">' +
            (raw ? val : esc(String(val))) + "</div></div>";
    }

    function strip_html(tone, text) {
        return '<div class="cvu-strip cvu-' + tone + '">' + esc(String(text)) + "</div>";
    }

    function target_card(r) {
        var st = status_of(r);
        var body = "";
        var headline = r.headline || "";
        if (headline) body = body + '<div class="cvu-headline">' + esc(headline) + "</div>";

        var rows = "";
        if (r.detail) rows = rows + row_html(__("Vehicle"), r.detail);
        if (r.sensors) {
            var ok = r.sensors_ok !== false && !/did not take|could not|missing|not importing/i.test(r.sensors);
            rows = rows + row_html(__("Sensors"),
                '<span class="cvu-pill cvu-' + (ok ? "green" : "red") + '">' + (ok ? "✓ " : "✕ ") +
                esc(String(r.sensors).replace(/^sensors:\s*/i, "")) + "</span>", true);
        }
        if (r.type_msg) {
            rows = rows + row_html(__("Vehicle type"),
                '<span class="cvu-pill cvu-' + (r.type_ok ? "green" : "red") + '">' + (r.type_ok ? "✓ " : "✕ ") +
                esc((r.vehicle_type ? r.vehicle_type + " — " : "") + String(r.type_msg)) + "</span>", true);
        }
        if (r.edited) rows = rows + row_html(__("Changed in the dialog"), r.edited);
        if (r.platform_said) {
            rows = rows + row_html(__("Platform reply"),
                '<span class="cvu-said">' + esc(r.platform_said) + "</span>", true);
        }
        if (!headline && !r.detail) rows = rows + row_html(__("Result"), r.result || "");
        body = body + rows;

        if ((r.gaps || []).length) {
            body = body + '<div class="cvu-strip cvu-orange"><b>' + __("Missing before it can be sent") +
                '</b><ul class="cvu-gaps">' + r.gaps.map(function (g) {
                    return "<li>" + esc(g) + "</li>";
                }).join("") + "</ul></div>";
        }
        if (r.advice) body = body + strip_html("orange", r.advice);

        return '<div class="cvu-card"><div class="cvu-card-head">' +
            '<span class="cvu-dot cvu-' + st[0] + '"></span>' +
            '<span class="cvu-title">' + esc(r.label) + "</span>" +
            '<span class="cvu-pill cvu-' + st[0] + '">' + esc(st[1]) + "</span></div>" +
            '<div class="cvu-body">' + body + "</div></div>";
    }

    function ticket_card(res) {
        var rows = "";
        var tone = "grey";
        var label = __("No change");
        if (res.server_status) {
            var s = res.server_status;
            tone = s === "uploaded" ? "green" : (s === "duplicate" ? "orange" : "red");
            label = s;
            rows = rows + row_html(__("Server status"),
                '<span class="cvu-pill cvu-' + tone + '">' + esc(s) + "</span>", true);
            if ((res.stamped || []).length) rows = rows + row_html(__("Ticket"), res.stamped.join(", "));
        } else if ((res.install_tickets || []).length) {
            rows = rows + row_html(__("Will be stamped"), (res.would_stamp || res.install_tickets).join(", "));
        }
        if (!rows && !res.note) return "";
        var body = rows + (res.note ? strip_html("blue", res.note) : "");
        return '<div class="cvu-card"><div class="cvu-card-head">' +
            '<span class="cvu-dot cvu-' + tone + '"></span>' +
            '<span class="cvu-title">' + __("Installation ticket") + "</span>" +
            '<span class="cvu-pill cvu-' + tone + '">' + esc(label) + "</span></div>" +
            '<div class="cvu-body">' + body + "</div></div>";
    }

    function notes_html(res) {
        card_css();
        var out = (res.results || []).map(target_card).join("") + ticket_card(res);
        if (res.warning) out = out + strip_html("orange", res.warning);
        if (!(res.live_targets || []).length) {
            out = out + strip_html("grey",
                __("This target is not in LIVE_TARGETS in the Server Script, so Upload Now will resolve everything and send nothing."));
        }
        return out;
