    // ---------------------------------------------------------------- vehicle-type picker
    // Tiles with an icon and the name, the way Pilot's own list looks. Pilot's icon font
    // cannot be loaded into the ERP (Pilot's server does not allow it), so these are the
    // ERP's own generic pictograms, matched to each type by its name.
    var COMMON_TYPES = ["Pickup", "Truck", "Light Truck", "Car", "Van", "Minibus", "Bus", "Lorry",
        "Road tractor", "Big rig", "Trailer", "Sided truck", "Tanker", "Refrigerator", "Mixer",
        "Delivery Truck", "Service Truck", "Autocrane", "Crane", "Excavator", "Loader", "Front Loader",
        "Tractor", "Motocycle"];

    function nice_type_name(n) {
        n = String(n || "").replace(/^А/, "A");
        if (n.indexOf("_") >= 0) {
            n = n.replace(/_/g, " ");
            n = n.charAt(0).toUpperCase() + n.slice(1);
        }
        return n;
    }

    function picker_css() {
        if (document.getElementById("cvt-picker-css")) return;
        var css = document.createElement("style");
        css.id = "cvt-picker-css";
        css.textContent = [
            ".cvt-wrap{margin-bottom:6px}",
            ".cvt-top{display:flex;gap:8px;align-items:center;margin-bottom:8px;flex-wrap:wrap}",
            ".cvt-top input{flex:1;min-width:160px}",
            ".cvt-chosen{font-size:12px;color:var(--text-muted);display:flex;align-items:center;gap:6px}",
            ".cvt-chosen b{color:var(--text-color)}",
            ".cvt-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(92px,1fr));gap:6px;",
            "  max-height:270px;overflow:auto;padding:2px}",
            ".cvt-sep{grid-column:1/-1;font-size:11px;color:var(--text-muted);margin:4px 0 0}",
            ".cvt-tile{display:flex;flex-direction:column;align-items:center;gap:4px;padding:7px 4px 6px;",
            "  border:1px solid var(--border-color);border-radius:8px;background:var(--fg-color,#fff);",
            "  color:var(--text-color);font-size:11px;line-height:1.2;cursor:pointer;text-align:center;position:relative}",
            ".cvt-tile:hover{border-color:var(--gray-500,#9ca3af)}",
            ".cvt-tile.is-on{border-color:var(--primary,#2490ef);box-shadow:0 0 0 1px var(--primary,#2490ef);",
            "  background:var(--control-bg,#f4f5f6);color:var(--primary,#2490ef)}",
            ".cvt-tile svg{flex:none}",
            ".cvt-tag{position:absolute;top:2px;right:3px;font-size:9px;font-weight:600;padding:0 4px;border-radius:6px;",
            "  background:var(--gray-100,#f1f1f3);color:var(--gray-700,#4b5563)}",
            ".cvt-tag.is-pilot{background:var(--blue-100,#e3eefd);color:var(--blue-800,#1e3a8a)}"
        ].join("\n");
        document.head.appendChild(css);
    }

    // $wrap: where to draw it. types: [{id, name}]. value: the id chosen now ("" = none).
    // opts.keep_label: offer a "keep what Pilot has" tile (value "").
    // opts.suggested: the id the ERP's own type points to. opts.current: Pilot's id now.
    function type_picker($wrap, types, value, opts) {
        opts = opts || {};
        picker_css();
        var state = { value: value ? String(value) : "" };
        var by_name = {};
        types.forEach(function (t) { by_name[String(t.name).toLowerCase()] = t; });
        var common = [];
        COMMON_TYPES.forEach(function (n) {
            var t = by_name[n.toLowerCase()];
            if (t) common.push(t);
        });
        var common_ids = {};
        common.forEach(function (t) { common_ids[t.id] = 1; });
        var rest = types.filter(function (t) { return !common_ids[t.id]; }).sort(function (a, b) {
            return nice_type_name(a.name).localeCompare(nice_type_name(b.name));
        });

        function tile(t) {
            var id = String(t.id);
            var tag = "";
            if (opts.current && String(opts.current) === id) tag = '<span class="cvt-tag is-pilot">' + __("Pilot") + "</span>";
            else if (opts.suggested && String(opts.suggested) === id) tag = '<span class="cvt-tag">' + __("ERP") + "</span>";
            return '<button type="button" class="cvt-tile" data-id="' + esc(id) + '" data-name="' +
                esc(nice_type_name(t.name).toLowerCase()) + '" title="' + esc(nice_type_name(t.name)) + '">' + tag +
                VT_ICONS.svg(t.name, 30) + "<span>" + esc(nice_type_name(t.name)) + "</span></button>";
        }
        var keep = opts.keep_label
            ? '<button type="button" class="cvt-tile" data-id="" data-name="' + esc(String(opts.keep_label).toLowerCase()) + '">' +
                '<svg viewBox="0 0 32 32" width="30" height="30" fill="none" stroke="currentColor" stroke-width="1.7" ' +
                'stroke-linecap="round" stroke-linejoin="round"><path d="M8 11a9 9 0 1 1-1.5 9M8 4v7h7"/></svg>' +
                "<span>" + esc(opts.keep_label) + "</span></button>"
            : "";
        $wrap.html(
            '<div class="cvt-wrap"><div class="cvt-top">' +
            '<input type="text" class="form-control input-xs cvt-search" placeholder="' + esc(__("Search vehicle type…")) + '">' +
            '<div class="cvt-chosen"></div></div>' +
            '<div class="cvt-grid">' + keep + common.map(tile).join("") +
            (rest.length ? '<div class="cvt-sep">' + esc(__("All types")) + "</div>" + rest.map(tile).join("") : "") +
            "</div>" + (opts.help ? '<div class="help-box small text-muted">' + opts.help + "</div>" : "") + "</div>");

        function paint() {
            $wrap.find(".cvt-tile").each(function () {
                this.classList.toggle("is-on", String(this.getAttribute("data-id")) === state.value);
            });
            var t = null;
            types.forEach(function (x) { if (String(x.id) === state.value) t = x; });
            $wrap.find(".cvt-chosen").html(t
                ? VT_ICONS.svg(t.name, 18) + __("Chosen:") + " <b>" + esc(nice_type_name(t.name)) + "</b>"
                : (opts.keep_label && state.value === "" ? "<b>" + esc(opts.keep_label) + "</b>"
                    : '<span style="color:var(--red-600,#dc2626)">' + esc(__("No type chosen yet")) + "</span>"));
        }
        $wrap.on("click", ".cvt-tile", function (e) {
            e.preventDefault();
            state.value = String(this.getAttribute("data-id") || "");
            paint();
        });
        $wrap.find(".cvt-search").on("input", function () {
            var q = String(this.value || "").trim().toLowerCase();
            $wrap.find(".cvt-tile").each(function () {
                var n = this.getAttribute("data-name") || "";
                this.style.display = (!q || n.indexOf(q) !== -1) ? "" : "none";
            });
            $wrap.find(".cvt-sep").css("display", q ? "none" : "");
        });
        paint();
        return {
            get: function () { return state.value; },
            name: function () {
                var n = "";
                types.forEach(function (x) { if (String(x.id) === state.value) n = nice_type_name(x.name); });
                return n;
            }
        };
    }

    // ---------------------------------------------------------------- editing
    // Pilot targets can be corrected in the dialog before anything is sent. The
    // edits go to the Server Script as `overrides` and change THIS upload only;
    // the Customer Vehicle record itself is not changed.
    // Edit exists for Pilot targets only (pilot_wsl, pilot2, pilot3 ...); IM targets are im, im2, ...
    function is_pilot_target(key) { return /^pilot/.test(String(key || "")); }
    var EDIT_KEYS = ["vehiclenumber", "uniqid", "msisdn", "configuration", "account_email", "type"];

    function is_editable(r) {
        return !!(is_pilot_target(r.target) && r.edit && r.payload && ("vehiclenumber" in r.payload));
    }

    // The value a field starts with: an earlier edit if there is one, else what the
    // server resolved from the ERP.
    function start_value(r, f, base) {
        var mine = (base || {})[r.target] || {};
        if (mine[f] !== undefined) return String(mine[f]);
        var p = r.payload || {};
        if (f === "account_email") return String(p._account_email || "");
        if (f === "type") return p._type_id ? String(p._type_id) : "";
        var v = p[f];
        return (v === undefined || v === null) ? "" : String(v);
    }

    function edit_fields(r, base) {
        var k = r.target;
        var p = r.payload || {};
        var o = r.edit || {};
        var types = (o.types || []).slice().sort(function (a, b) {
            return String(a.name).localeCompare(String(b.name));
        });
        var cfgs = (o.configurations || []).slice().sort();

        var type_help = p._vehicle_type
            ? __("ERP type: {0}", [esc(p._vehicle_type)])
            : __("This vehicle has no type in the ERP — choose one.");
        if (o.types_error) {
            type_help = __("Pilot's vehicle-type list could not be read ({0}). Type the type id, or leave it empty to keep Pilot's default.",
                [esc(o.types_error)]);
        }
        if (!o.node) {
            type_help = type_help + "<br>" +
                __("No node is set for this estate in app_apis, so the type cannot be set after the vehicle is created.");
        }

        var acc = p.account_id && String(p.account_id) !== "0"
            ? __("Pilot account {0} — {1}", [esc(String(p.account_id)), esc(p.account_name || "")])
            : __("No Pilot account found for this email yet.");

        // With Pilot's list: icon tiles (drawn after the dialog opens). Without it: a plain id box.
        var type_fields = types.length
            ? [{ fieldtype: "Section Break", label: r.label + " — " + __("vehicle type") },
                { fieldtype: "HTML", fieldname: k + "__type_html", options: "" }]
            : [];
        var type_field = types.length ? null
            : { fieldtype: "Data", fieldname: k + "__type", label: __("Vehicle type id"),
                "default": start_value(r, "type", base), description: type_help };
        r._type_help = type_help;

        var cfg_field = cfgs.length
            ? { fieldtype: "Autocomplete", fieldname: k + "__configuration", options: cfgs }
            : { fieldtype: "Data", fieldname: k + "__configuration" };
        cfg_field.label = __("Device type (configuration)");
        cfg_field.reqd = 1;
        cfg_field["default"] = start_value(r, "configuration", base);
        cfg_field.description = p._device_type ? __("ERP device type: {0}", [esc(p._device_type)]) : "";

        return [
            { fieldtype: "Section Break", label: r.label + " — " + __("check and correct before uploading") },
            { fieldtype: "Data", fieldname: k + "__vehiclenumber", label: __("Vehicle number (plate)"), reqd: 1,
                "default": start_value(r, "vehiclenumber", base) },
            { fieldtype: "Data", fieldname: k + "__uniqid", label: __("IMEI (uniqid)"), reqd: 1,
                "default": start_value(r, "uniqid", base) },
            { fieldtype: "Data", fieldname: k + "__msisdn", label: __("SIM number (msisdn)"),
                "default": start_value(r, "msisdn", base), description: __("0 = no SIM") },
            { fieldtype: "Column Break" },
            cfg_field,
            { fieldtype: "Data", fieldname: k + "__account_email", label: __("Platform account email"), reqd: 1,
                "default": start_value(r, "account_email", base), description: acc }
        ].concat(type_field ? [type_field] : []).concat(type_fields);
    }

    function show_plan(frm, target, res, base_edits) {
        var rows = res.results || [];
        base_edits = base_edits || {};
        if (!rows.length) {
            frappe.msgprint({ title: __("Nothing to upload"), indicator: "orange",
                message: esc(res.error || __("No platform matched this vehicle.")) });
            return;
        }

        // Two ways out of this dialog:
        //   Verify & Stamp -- asks the platform whether the device is there and
        //                     stamps the ticket from the answer. Works today.
        //   Upload Now     -- pushes the vehicle to the platform, with the edits
        //                     made here.
        // A target with no create command cannot be pushed, so there the only
        // button is Verify. Everywhere else the big button is the upload --
        // the dialog is called Upload, and Verify beside it was being pressed
        // by mistake for it.
        var blocked = rows.every(function (r) { return r.blocked; });
        var editable = rows.filter(is_editable);

        // The edits to send: earlier ones, plus every field that now differs from
        // what it started with. Null when a required field is empty.
        var pickers = {};
        function collect(strict) {
            var vals = editable.length ? (strict ? d.get_values() : d.get_values(true)) : {};
            if (!vals) return null;
            if (strict) {
                var unchosen = editable.filter(function (r) { return pickers[r.target] && !pickers[r.target].get(); });
                if (unchosen.length) {
                    frappe.msgprint({ title: __("Choose the vehicle type"), indicator: "orange",
                        message: __("Pick the vehicle type for {0} before uploading.", [unchosen.map(function (r) { return r.label; }).join(", ")]) });
                    return null;
                }
            }
            var edits = {};
            editable.forEach(function (r) {
                var e = $.extend({}, base_edits[r.target] || {});
                EDIT_KEYS.forEach(function (f) {
                    var v = (f === "type" && pickers[r.target]) ? pickers[r.target].get() : vals[r.target + "__" + f];
                    v = (v === undefined || v === null) ? "" : String(v).trim();
                    if (v !== start_value(r, f, base_edits)) e[f] = v;
                });
                if (Object.keys(e).length) edits[r.target] = e;
            });
            return edits;
        }

        function go(action, busy, edits) {
            d.get_primary_btn().prop("disabled", true);
            frappe.dom.freeze(busy);
            run(frm, target, action, function (r2) {
                frappe.dom.unfreeze();
                d.hide();
                report(frm, r2);
            }, function (msg) {
                frappe.dom.unfreeze();
                d.hide();
                fail(msg, null, action === "upload"
                    ? __("The vehicle may already have been created. Press Verify & Stamp before uploading again.") : "");
            }, edits);
        }
        function do_upload() {
            var edits = collect(true);
            if (edits === null) return;   // get_values already said which field is missing
            go("upload", __("Uploading to the platform..."), edits);
        }
        function do_verify() { go("verify", __("Checking the platform...")); }

        // Re-check: build the payload again WITH the edits, so the account, the
        // device type and the gaps below are worked out from what will be sent.
        function do_recheck() {
            var edits = collect(false) || {};
            frappe.dom.freeze(__("Checking your changes..."));
            run(frm, target, "plan", function (r2) {
                frappe.dom.unfreeze();
                d.hide();
                show_plan(frm, target, r2, edits);
            }, function (msg) {
                frappe.dom.unfreeze();
                fail(msg);
            }, edits);
        }

        // Which buttons this dialog gets, after the switches at the top.
        var can_upload = !blocked && !!SHOW_UPLOAD_NOW;
        var can_verify = !!SHOW_VERIFY_STAMP;

        var fields = [];
        editable.forEach(function (r) { fields = fields.concat(edit_fields(r, base_edits)); });
        if (editable.length) fields.push({ fieldtype: "Section Break" });
        fields.push({ fieldtype: "HTML", fieldname: "body" });

        var opts = {
            title: __("Upload") + " — " + (res.plate || frm.doc.name),
            size: "large",
            fields: fields
        };
        if (can_upload) {
            opts.primary_action_label = __("Upload Now");
            opts.primary_action = do_upload;
            if (can_verify) {
                opts.secondary_action_label = __("Verify & Stamp");
                opts.secondary_action = do_verify;
            }
        } else if (can_verify) {
            opts.primary_action_label = __("Verify & Stamp");
            opts.primary_action = do_verify;
        } else {
            // both buttons switched off: the dialog only shows the payload
            opts.primary_action_label = __("Close");
            opts.primary_action = function () { d.hide(); };
        }
        var d = new frappe.ui.Dialog(opts);

        var help = [];
        if (editable.length) {
            help.push("<b>" + __("Re-check") + "</b> — " +
                __("works the payload out again with your changes (account, device type, missing values). It sends nothing."));
        }
        if (can_verify) {
            help.push("<b>" + __("Verify &amp; Stamp") + "</b> — " +
                __("asks the platform whether this device is registered and sets the Installation ticket's Server status from the answer. It writes nothing to Pilot or IM."));
        }
        if (SHOW_UPLOAD_NOW) {
            help.push("<b>" + __("Upload Now") + "</b> — " +
                __("creates the vehicle on the platform with the values above, your changes included, then sets the chosen vehicle type. Only runs for a target listed in LIVE_TARGETS in the Server Script. Your changes are used for this upload only; the vehicle record is not changed."));
        }

        d.fields_dict.body.$wrapper.html(
            '<div style="font-size:13px">' +
            '<div style="color:var(--text-muted);margin-bottom:8px">' +
            (editable.length
                ? __("Resolved from the ERP (and your changes, after Re-check). Correct anything above before uploading.")
                : __("This is exactly what would be sent. Check it before uploading.")) + "</div>" +
            (editable.length
                ? '<div style="margin-bottom:8px"><button class="btn btn-default btn-xs cvu-recheck">' +
                    __("Re-check with my changes") + "</button></div>"
                : "") +
            payload_table(rows) + notes_html(res) +
            (help.length
                ? '<div style="margin-top:10px;padding:8px 10px;border-radius:6px;' +
                    'background:var(--bg-color);border:1px solid var(--border-color);font-size:11px">' +
                    help.join("<br>") + "</div>"
                : "") +
            "</div>");
        d.fields_dict.body.$wrapper.find(".cvu-recheck").on("click", function (e) {
            e.preventDefault();
            do_recheck();
        });
        editable.forEach(function (r) {
            var f = d.fields_dict[r.target + "__type_html"];
            if (!f) return;
            pickers[r.target] = type_picker(f.$wrapper, (r.edit || {}).types || [], start_value(r, "type", base_edits), {
                suggested: (r.payload || {})._type_id || "",
                help: r._type_help || ""
            });
        });

        d.show();
    }

    function report(frm, res) {
        var ok = !!res.ok;
        var checked = res.action === "verify";
        var edited = res.action === "edit_save";
        var unsent = !checked && !edited && res.not_sent && res.not_sent.length;
        frappe.msgprint({
            title: edited
                ? (ok ? __("Saved on Pilot") : __("Not Saved on Pilot"))
                : checked
                ? (ok ? __("Verified — Registered") : __("Verified — Not Registered"))
                : (ok ? __("Uploaded") : (unsent ? __("Not Sent") : __("Not Uploaded"))),
            indicator: ok ? "green" : (unsent ? "orange" : "red"),
            wide: true,
            message: '<div style="font-size:13px">' +
                (res.plate ? '<div style="color:var(--text-muted)">' + esc(res.plate) +
                    (res.imei ? " · IMEI " + esc(res.imei) : "") + "</div>" : "") +
                notes_html(res) + "</div>"
        });
        frm.reload_doc();
    }

    function fail(msg, title, hint) {
        card_css();
        frappe.msgprint({ title: title || __("Upload Failed"), indicator: "red",
            message: '<div class="cvu-card"><div class="cvu-card-head"><span class="cvu-dot cvu-red"></span>' +
                '<span class="cvu-title">' + __("The request did not complete") + "</span></div>" +
                '<div class="cvu-body"><span class="cvu-said">' +
                esc(String(msg || __("The server did not answer."))) + "</span>" +
                (hint ? strip_html("orange", hint) : "") + "</div></div>" });
    }

    function run(frm, target, action, done, oops, edits) {
        var args = { action: action, target: target, vehicle: frm.doc.name };
        if (edits && Object.keys(edits).length) args.overrides = JSON.stringify(edits);
        frappe.call({
            method: METHOD,
            args: args,
            callback: function (r) {
                var res = r && r.message ? r.message : null;
                if (!res) { oops(__("Empty response.")); return; }
                if (res.error) { oops(res.error); return; }
                done(res);
            },
            error: function (e) {
                oops((e && e.message) || __("The call did not go through."));
            }
        });
    }

    // ---------------------------------------------------------------- delete
    // Delete this vehicle from ONE platform. Looks it up first (deletes nothing), shows what it
    // found, and only deletes after DELETE is typed (plus the IM Security PIN if IM asks for it).
    // Cannot be undone on the platform; the ERP vehicle record is not touched.
    function api(args, done) {
        frappe.call({
            method: METHOD,
            args: args,
            callback: function (r) { done((r && r.message) || { error: __("Empty response.") }); },
            error: function (e) { done({ error: (e && e.message) || __("The call did not go through.") }); }
        });
    }

    // The Delete dropdown is a button of its own, painted dark red so it is not mistaken for Upload.
    function paint_group(frm, group, cls, bg, hover) {
        var css_id = cls + "-" + String(group).replace(/[^A-Za-z0-9]/g, "_");
        if (!document.getElementById(css_id)) {
            var css = document.createElement("style");
            css.id = css_id;
            css.textContent =
                '.inner-group-button[data-label="' + group + '"] > button.btn,' +
                " .btn." + cls + " {" +
                "  background:" + bg + " !important; border-color:" + bg + " !important;" +
                "  color:#fff !important; font-weight:500;" +
                "}" +
                '.inner-group-button[data-label="' + group + '"] > button.btn:hover,' +
                " .btn." + cls + ":hover { background:" + hover + " !important; border-color:" + hover + " !important; color:#fff !important; }" +
                '.inner-group-button[data-label="' + group + '"] > button.btn svg,' +
                " .btn." + cls + " svg { fill:#fff !important; stroke:#fff !important; }";
            document.head.appendChild(css);
        }
        try {
            frm.page.wrapper.find(".custom-actions .inner-group-button > button.btn")
                .each(function () {
                    if ((this.textContent || "").trim().indexOf(group) === 0) {
                        this.classList.add(cls);
                    }
                });
        } catch (e) { /* cosmetic */ }
    }
    function paint_other(frm, group) { paint_group(frm, group, "cv-other-amber", "#9a3412", "#7c2d12"); }

    function delete_state_label(state) {
        return {
            found: __("Found on the platform"), missing: __("Not on the platform"),
            mismatch: __("A vehicle with this name has a different IMEI"),
            unknown: __("Could not check"), skipped: __("No Device Serial"),
            suspended: __("Already suspended")
        }[state] || state;
    }

    // check_only: the read-only "Check vehicle" -- the same look-up, no delete.
    function delete_flow(frm, target, check_only) {
        card_css();
        frappe.dom.freeze(__("Looking the vehicle up on {0}...", [target.label]));
        api({ action: "delete_plan", target: target.key, connection: target.connection || "", vehicle: frm.doc.name }, function (res) {
            frappe.dom.unfreeze();
            var row = (res.results && res.results[0]) || { state: "unknown", detail: res.error || __("No answer.") };
            if (res.error && !(res.results && res.results.length)) row.detail = res.error;
            var can = !check_only && row.state === "found";
            var tone = row.state === "found" ? "green" : (row.state === "missing" ? "grey" : "red");

            var d = new frappe.ui.Dialog({
                title: (check_only ? __("Check vehicle on {0}", [target.label]) : target.title) + " — " + (res.plate || frm.doc.name),
                fields: [
                    { fieldtype: "HTML", fieldname: "body" },
                    { fieldtype: "Data", fieldname: "confirm", label: __("Type {0} to confirm", [target.word]), hidden: can ? 0 : 1 },
                    { fieldtype: "Password", fieldname: "pin", label: __("IM Security PIN"), hidden: (can && row.pin_needed) ? 0 : 1 }
                ],
                primary_action_label: target.title,
                primary_action: function () {
                    if (String(d.get_value("confirm") || "").trim() !== target.word) {
                        frappe.msgprint({ title: __("Not confirmed"), indicator: "orange",
                            message: __("Type {0} in the box to continue.", [target.word]) });
                        return;
                    }
                    var pin = String(d.get_value("pin") || "").trim();
                    if (row.pin_needed && !pin) {
                        frappe.msgprint({ title: __("Security PIN"), indicator: "orange",
                            message: __("IM asks for its Security PIN before it deletes.") });
                        return;
                    }
                    d.get_primary_btn().prop("disabled", true);
                    frappe.dom.freeze(target.busy);
                    api({ action: "delete", target: target.key, connection: target.connection || "", vehicle: frm.doc.name, confirm: target.word, pin: pin }, function (r2) {
                        frappe.dom.unfreeze();
                        d.hide();
                        var out = (r2.results && r2.results[0]) || { verdict: "failure", result: r2.error || __("No answer.") };
                        if (r2.error && !(r2.results && r2.results.length)) out.result = r2.error;
                        var ok = out.verdict === "deleted" || out.verdict === "done";
                        frappe.msgprint({
                            title: ok ? target.done : __("Not done"),
                            indicator: ok ? "green" : "red",
                            message: '<div class="cvu-card"><div class="cvu-card-head"><span class="cvu-dot cvu-' + (ok ? "green" : "red") +
                                '"></span><span class="cvu-title">' + esc(target.label) + "</span></div>" +
                                '<div class="cvu-body">' + esc(out.result || "") + "</div></div>"
                        });
                        frm.reload_doc();
                    });
                }
            });
            if (!can) {
                d.get_primary_btn().hide();
            } else {
                d.get_primary_btn().addClass("btn-danger");
            }
            d.fields_dict.body.$wrapper.html(
                '<div style="font-size:13px">' +
                '<div class="cvu-card"><div class="cvu-card-head">' +
                '<span class="cvu-dot cvu-' + tone + '"></span><span class="cvu-title">' + esc(target.label) + "</span>" +
                '<span class="cvu-pill cvu-' + tone + '">' + esc(delete_state_label(row.state)) + "</span></div>" +
                '<div class="cvu-body">' + row_html(__("Vehicle"), (res.plate || frm.doc.name) + (res.imei ? " · IMEI " + res.imei : "")) +
                row_html(__("On the platform"), row.detail || "") + "</div></div>" +
                (can ? strip_html("orange", target.warn) : "") + "</div>");
            d.show();
        });
    }

    // Check SIM: read-only. Shows what Lebara knows about this vehicle's SIM; changes nothing.
    function check_sim_flow(frm) {
        card_css();
        frappe.dom.freeze(__("Asking Lebara about the SIM..."));
        api({ action: "sim_check", vehicle: frm.doc.name }, function (res) {
            frappe.dom.unfreeze();
            var sim = res.sim;
            var head = (res.plate || frm.doc.name) + (res.imei ? " · IMEI " + res.imei : "");
            if (!sim) {
                frappe.msgprint({
                    title: __("Check SIM"), indicator: "orange",
                    message: '<div style="color:var(--text-muted);margin-bottom:6px">' + esc(head) + "</div>" +
                        strip_html("orange", res.error || res.why || __("No SIM found."))
                });
                return;
            }
            var tone = sim.status === "Active" ? "green" : (sim.status === "Suspend" || sim.status === "Bar" ? "orange" : "grey");
            var match = sim.imei_matches_vehicle;
            var rows =
                row_html(__("Status"), '<span class="cvu-pill cvu-' + tone + '">' + esc(sim.status || "?") + "</span>", true) +
                row_html(__("Number"), sim.msisdn) +
                row_html(__("ICCID"), sim.iccid) +
                row_html(__("IMSI"), sim.imsi) +
                row_html(__("Group"), sim.group) +
                row_html(__("Customer"), sim.customer) +
                row_html(__("Activated"), sim.activated) +
                row_html(__("Last connection"), sim.last_connection) +
                row_html(__("Usage this month (MB)"), sim.this_month_usage) +
                row_html(__("Usage last month (MB)"), sim.last_month_usage) +
                row_html(__("In a data session"), sim.in_data_session) +
                row_html(__("Device it was last in (IMEI)"), sim.sim_imei +
                    (match === "yes" ? " ✓ " + __("this vehicle's device")
                        : (match === "no" ? " ✕ " + __("not this vehicle's device") : ""))) +
                (sim.live_status ? row_html(__("Live status"), '<span class="cvu-said">' + esc(sim.live_status) + "</span>", true) : "");
            frappe.msgprint({
                title: __("Check SIM"), indicator: tone === "green" ? "green" : "orange", wide: true,
                message: '<div style="color:var(--text-muted);margin-bottom:6px">' + esc(head) + "</div>" +
                    '<div class="cvu-card"><div class="cvu-card-head"><span class="cvu-dot cvu-' + tone + '"></span>' +
                    '<span class="cvu-title">' + __("Lebara SIM") + "</span></div>" +
                    '<div class="cvu-body">' + rows + "</div></div>" +
                    (match === "no" ? strip_html("orange", __("Lebara last saw this SIM in a different device than this vehicle's.")) : "")
            });
        });
    }

    // ---------------------------------------------------------------- edit on Pilot
    // Change a vehicle that is ALREADY on Pilot: plate, IMEI, SIM, device type and vehicle
    // type. The dialog opens with Pilot's own current values, Save is always on, and only
    // the fields you change are sent. The ERP vehicle record itself is not changed.
    var PILOT_FIELDS = ["vehiclenumber", "uniqid", "msisdn", "configuration"];

    function edit_flow(frm, key, label, pilot_imei, compare_imei) {
        frappe.dom.freeze(__("Reading the vehicle from {0}...", [label]));
        api({ action: "edit_plan", target: key, vehicle: frm.doc.name,
            pilot_imei: pilot_imei || "", compare_imei: compare_imei || "" }, function (res) {
            frappe.dom.unfreeze();
            if (res.error) {
                if (res.not_found) {
                    var p = frappe.prompt([
                        { fieldtype: "HTML", fieldname: "why",
                            options: '<div class="text-muted small" style="margin-bottom:8px">' + esc(res.error) +
                                "<br>" + esc(__("If the device on Pilot has a different IMEI, type it here.")) + "</div>" },
                        { fieldtype: "Data", fieldname: "imei", label: __("IMEI on {0}", [label]), reqd: 1,
                            "default": pilot_imei || frm.doc.device_serial || "" }
                    ], function (v) { edit_flow(frm, key, label, String(v.imei || "").trim()); },
                    __("Not found on {0}", [label]), __("Search"));
                    return p;
                }
                fail(res.error, __("Edit on Pilot"));
                return;
            }
            show_edit(frm, key, label, res);
        });
    }

    function record_check_html(res) {
        var pilot = res.pilot || {};
        var chk = pilot.check || {};
        var parts = [];
        if (!pilot.record_ok) {
            parts.push(strip_html("orange", __("Pilot's full record of this vehicle could not be read: {0}", [pilot.record_why || ""])));
        } else {
            var empty = (chk.empty || []).concat((chk.config_empty || []).map(function (k) { return "config." + k; }));
            if (chk.config_blank) empty.push(__("config (all settings)"));
            parts.push(row_html(__("Empty on Pilot"), empty.length ? empty.join(", ") : __("nothing — every field has a value")));
            parts.push(row_html(__("Group (folder)"), pilot.folder_id ? pilot.folder_id : __("none")));
        }
        var cmp = res.compare;
        if (cmp && cmp.error) parts.push(strip_html("orange", __("Compare: {0}", [cmp.error])));
        if (cmp && !cmp.error) {
            var miss = (cmp.empty_only_here || []).concat((cmp.config_empty_only_here || []).map(function (k) { return "config." + k; }))
                .concat((cmp.config_keys_missing_here || []).map(function (k) { return "config." + k + " " + __("(missing)"); }))
                .concat((cmp.keys_missing_here || []).map(function (k) { return k + " " + __("(missing)"); }));
            parts.push(row_html(__("Compared with"), cmp.detail || cmp.imei));
            parts.push(row_html(__("Set there, empty here"), miss.length ? miss.join(", ") : __("no difference found")));
        }
        return '<div class="cvu-card"><div class="cvu-card-head"><span class="cvu-dot cvu-blue"></span>' +
            '<span class="cvu-title">' + __("Pilot record check") + "</span></div><div class=\"cvu-body\">" +
            '<div class="text-muted small" style="margin-bottom:6px">' +
            esc(__("Pilot's own vehicle editor keeps Save switched off while a required field is empty — even for an admin. This lists what Pilot holds empty for this vehicle.")) +
            "</div>" + parts.join("") +
            '<div style="display:flex;gap:6px;margin-top:8px;align-items:center">' +
            '<input type="text" class="form-control input-xs cve-cmp" style="max-width:220px" placeholder="' +
            esc(__("IMEI of a vehicle made in Pilot")) + '">' +
            '<button class="btn btn-default btn-xs cve-cmp-go">' + __("Compare") + "</button></div></div></div>";
    }

    function show_edit(frm, key, label, res) {
        card_css();
        var pilot = res.pilot || {};
        var cur = pilot.current || {};
        var o = res.edit || {};
        var cfgs = (o.configurations || []).slice().sort();
        var no_panel = (pilot.missing_mileage || []).length > 0;
        var lock_note = no_panel
            ? __("Locked: Pilot's search does not return {0}, and saving these fields could reset the mileage.", [pilot.missing_mileage.join(", ")])
            : "";
        function val(k) { return (cur[k] === undefined || cur[k] === null) ? "" : String(cur[k]); }

        var cfg_field = cfgs.length
            ? { fieldtype: "Autocomplete", fieldname: "configuration", options: cfgs }
            : { fieldtype: "Data", fieldname: "configuration" };
        cfg_field.label = __("Device type (configuration)");
        cfg_field["default"] = val("configuration");
        cfg_field.read_only = no_panel ? 1 : 0;

        var fields = [
            { fieldtype: "HTML", fieldname: "head" },
            { fieldtype: "Section Break", label: __("Vehicle on {0}", [label]) },
            { fieldtype: "Data", fieldname: "vehiclenumber", label: __("Vehicle number (plate)"), "default": val("vehiclenumber"), read_only: no_panel ? 1 : 0 },
            { fieldtype: "Data", fieldname: "uniqid", label: __("IMEI (uniqid)"), "default": val("uniqid"), read_only: no_panel ? 1 : 0,
                description: __("Change only when the device was replaced.") },
            { fieldtype: "Data", fieldname: "msisdn", label: __("SIM number (msisdn)"), "default": val("msisdn"), read_only: no_panel ? 1 : 0,
                description: __("0 = no SIM") },
            { fieldtype: "Column Break" },
            cfg_field,
            { fieldtype: "HTML", fieldname: "account" },
            { fieldtype: "Section Break", label: __("Vehicle type") },
            { fieldtype: "HTML", fieldname: "type_html" },
            { fieldtype: "Section Break", label: __("Pilot record check") },
            { fieldtype: "HTML", fieldname: "check" }
        ];
        if (!(o.types || []).length) {
            fields.splice(fields.length - 3, 1, { fieldtype: "Data", fieldname: "type_id", label: __("Vehicle type id"),
                description: __("Pilot's vehicle-type list could not be read ({0}). Leave empty to keep the type Pilot has.", [esc(o.types_error || "")]) });
        }

        var d = new frappe.ui.Dialog({
            title: __("Edit on {0}", [label]) + " — " + (val("vehiclenumber") || res.plate || frm.doc.name),
            size: "large",
            fields: fields,
            primary_action_label: __("Save to {0}", [label]),
            primary_action: do_save
        });

        d.fields_dict.head.$wrapper.html('<div class="text-muted small">' +
            esc(__("These are the values Pilot has now ({0}). Change what you need and press Save — only the fields you change are sent. The vehicle record in the ERP is not changed.", [pilot.detail || ""])) +
            (lock_note ? strip_html("orange", lock_note) : "") +
            (!o.node ? strip_html("orange", __("No node is set for this estate in app_apis, so the vehicle type cannot be changed.")) : "") +
            "</div>");
        d.fields_dict.account.$wrapper.html('<div class="form-group"><div class="clearfix"><label class="control-label">' +
            __("Pilot account") + '</label></div><div class="control-value like-disabled-input">' +
            esc((val("account_id") || "?") + " — " + val("account_name")) + "</div>" +
            '<p class="help-box small text-muted">' + esc(__("Moving a vehicle to another account is done on Pilot.")) + "</p></div>");

        var picker = null;
        if (d.fields_dict.type_html) {
            var sug = res.suggest_type || {};
            picker = type_picker(d.fields_dict.type_html.$wrapper, o.types || [], "", {
                keep_label: __("Keep the type Pilot has"),
                current: pilot.current_type_id || "",
                suggested: sug.id || "",
                help: (pilot.current_type_id ? esc(__("“Pilot” marks the type it has now.")) + " " : "") +
                    (sug.erp ? esc(__("“ERP” marks the type matching the ERP's {0}.", [sug.erp])) : "")
            });
        }
        d.fields_dict.check.$wrapper.html(record_check_html(res));
        d.fields_dict.check.$wrapper.find(".cve-cmp-go").on("click", function (e) {
            e.preventDefault();
            var other = String(d.fields_dict.check.$wrapper.find(".cve-cmp").val() || "").trim();
            if (!other) return;
            d.hide();
            edit_flow(frm, key, label, res.imei, other);
        });

        function do_save() {
            var vals = d.get_values(true) || {};
            var edits = {};
            var lines = [];
            if (!no_panel) {
                PILOT_FIELDS.forEach(function (f) {
                    var v = vals[f] === undefined || vals[f] === null ? "" : String(vals[f]).trim();
                    if (v !== val(f)) {
                        edits[f] = v;
                        lines.push("<li><b>" + esc(f) + "</b>: " + esc(val(f) || "(empty)") + " → " + esc(v || "(empty)") + "</li>");
                    }
                });
            }
            var t = picker ? picker.get() : String(vals.type_id || "").trim();
            if (t) {
                edits.type = t;
                lines.push("<li><b>" + esc(__("vehicle type")) + "</b> → " + esc(picker ? picker.name() : ("id " + t)) + "</li>");
            }
            if (!lines.length) {
                frappe.show_alert({ message: __("Nothing changed — every value is what Pilot has."), indicator: "orange" });
                return;
            }
            frappe.confirm('<div style="font-size:13px">' + esc(__("Save these changes to {0}?", [label])) +
                '<ul style="margin:8px 0 0 18px;padding:0">' + lines.join("") + "</ul></div>", function () {
                d.get_primary_btn().prop("disabled", true);
                frappe.dom.freeze(__("Saving to {0}...", [label]));
                var payload = {};
                payload[key] = edits;
                api({ action: "edit_save", target: key, vehicle: frm.doc.name, agent_id: String(cur.agent_id || ""),
                    pilot_imei: res.imei || "", overrides: JSON.stringify(payload) }, function (r2) {
                    frappe.dom.unfreeze();
                    d.hide();
                    if (r2.error && !(r2.results || []).length) { fail(r2.error, __("Edit on Pilot")); return; }
                    report(frm, r2);
                });
            });
        }

        d.show();
    }

    // ---------------------------------------------------------------- wiring
    function needs_device(frm, what) {
        if (String(frm.doc.device_serial || "").trim()) return false;
        frappe.msgprint({ title: __("No Device"), indicator: "red",
            message: what === "upload"
                ? __("This vehicle has no Device Serial, so there is nothing to register.")
                : __("This vehicle has no Device Serial, so there is nothing to look for.") });
        return true;
    }

    function upload(frm, key) {
        if (needs_device(frm, "upload")) return;
        frappe.dom.freeze(__("Building the payload..."));
        run(frm, key, "plan", function (res) {
            frappe.dom.unfreeze();
            show_plan(frm, key, res);
        }, function (msg) {
            frappe.dom.unfreeze();
            fail(msg);
        });
    }

    // One dropdown per Pilot connection (and IM): every action for that platform in one place.
    function platform_buttons(frm, con) {
        var group = con.label;
        var target = platform_delete(con.key, con.label);
        if (SHOW_UPLOAD) frm.add_custom_button(__("Upload"), function () { upload(frm, con.key); }, group);
        if (SHOW_EDIT && !con.is_im) {
            frm.add_custom_button(__("Edit"), function () {
                if (needs_device(frm)) return;
                edit_flow(frm, con.key, con.label);
            }, group);
        }
        if (SHOW_CHECK_VEHICLE) {
            frm.add_custom_button(__("Check vehicle"), function () {
                if (needs_device(frm)) return;
                delete_flow(frm, target, true);
            }, group);
        }
        if (SHOW_DELETE) {
            frm.add_custom_button(__("Delete"), function () {
                if (needs_device(frm)) return;
                delete_flow(frm, target);
            }, group);
        }
        if (con.uses_wasl && SHOW_REMOVE_WASL) {
            frm.add_custom_button(__("Remove from WASL"), function () {
                if (needs_device(frm)) return;
                delete_flow(frm, wasl_delete(con));
            }, group);
        }
        paint_black(frm, group);
    }

    frappe.ui.form.on("Customer Vehicle", {
        refresh: function (frm) {
            if (frm.is_new() || !may_upload()) return;

            with_connections(function (cons) { with_im_connections(function (ims) {
                if (frm.is_new()) return;
                cons.forEach(function (con) { platform_buttons(frm, con); });
                if (SHOW_IM) ims.forEach(function (con) {
                    platform_buttons(frm, { key: con.key, label: con.label, uses_wasl: false, is_im: true });
                });

                if (SHOW_ALL_PLATFORMS) frm.add_custom_button(__("Upload to all"), function () { upload(frm, "all"); });

                if (SHOW_CHECK_SIM) {
                    frm.add_custom_button(__("Check SIM"), function () {
                        if (needs_device(frm)) return;
                        check_sim_flow(frm);
                    }, SIM_GROUP);
                }
                if (SHOW_SUSPEND_SIM) {
                    frm.add_custom_button(__("Suspend SIM"), function () {
                        if (needs_device(frm)) return;
                        delete_flow(frm, SIM_SUSPEND);
                    }, SIM_GROUP);
                }
                if (SHOW_CHECK_SIM || SHOW_SUSPEND_SIM) paint_other(frm, SIM_GROUP);
            }); });
        }
    });
})();

// =============================================================================
// customer-vehicle-systems  --  Client Script (dt = Customer Vehicle, view = Form)
// =============================================================================
//
// A "Summary" section at the top of the vehicle form: where the device is, whether the vehicle is
// linked to WASL, the state of its SIM, and whether that SIM was last seen in THIS vehicle's device.
//
// It calls no outside system. It reads what the app already keeps up to date --
//   SIM            "Lebara SIM Sync", every hour
//   WASL           "App Apis - WASL Status Sync", every hour
//   where it is    the Fleet Audit report (what the Pilot and IM estates said; refreshed from the Fleet Audit block)
// -- through app_apis.vehicle_systems.get_systems, and shows how old each part is.
// =============================================================================

(function () {
    // ------------------------------------------------------------ switches
    // 1 = shown, 0 = hidden. Change it, save the Client Script, reload the form.
    var SHOW_SYSTEMS_SECTION = 1;
    // ---------------------------------------------------------------------------

    var METHOD = "app_apis.vehicle_systems.get_systems";
    var SECTION = "cv-systems";
    var esc = frappe.utils.escape_html;

    function css() {
        if (document.getElementById("cvs-css")) return;
        var s = document.createElement("style");
        s.id = "cvs-css";
        s.textContent = [
            ".cvs-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}",
            ".cvs-box{border:1px solid var(--border-color);border-radius:10px;padding:10px 12px;background:var(--card-bg,var(--bg-color))}",
            ".cvs-h{font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.04em;color:var(--text-muted);margin-bottom:6px}",
            ".cvs-line{display:flex;align-items:center;gap:8px;padding:2px 0;font-size:13px}",
            ".cvs-line .k{flex:1}",
            ".cvs-sub{font-size:11px;color:var(--text-muted);margin-top:4px}",
            ".cvs-pill{font-size:11px;font-weight:600;padding:2px 9px;border-radius:999px;white-space:nowrap}",
            ".cvs-green{background:var(--green-100,#e4f5e9);color:var(--green-800,#14532d)}",
            ".cvs-red{background:var(--red-100,#fde8e8);color:var(--red-800,#7f1d1d)}",
            ".cvs-orange{background:var(--orange-100,#fdf0e1);color:var(--orange-800,#7c2d12)}",
            ".cvs-grey{background:var(--gray-100,#f1f1f3);color:var(--gray-700,#4b5563)}",
            ".cvs-issues{margin-top:10px;padding:8px 12px;border-radius:8px;font-size:12px;border:1px solid var(--orange-200,#f8d3a8);",
            "  background:var(--orange-100,#fdf0e1);color:var(--orange-800,#7c2d12)}",
            ".cvs-issues ul{margin:4px 0 0 18px;padding:0}",
            ".cvs-stale{color:var(--orange-700,#9a3412)}"
        ].join("\n");
        document.head.appendChild(s);
    }

    function pill(text, tone) {
        return '<span class="cvs-pill cvs-' + tone + '">' + esc(text) + "</span>";
    }

    function age(part) {
        if (!part || !part.as_of) return "";
        var txt = esc(part.as_of);
        if (part.stale && part.age_days !== null && part.age_days !== undefined) {
            return '<span class="cvs-stale">' + txt + " · " + esc(part.age_days) + " " + __("days old") + "</span>";
        }
        return txt;
    }

    // Where it is: ONLY what the systems reported to the Fleet Audit (Pilot and IM estates). Nothing here
    // comes from the vehicle's own Platforms boxes or account emails.
    function where_box(d) {
        var rows = d.where.map(function (w) {
            var p;
            if (w.note) p = pill(__("not read"), "grey");
            else if (w.on === null) p = pill(__("no audit data"), "grey");
            else if (w.on) p = pill(__("found"), "green");
            else p = pill(__("not found"), "red");
            var extra = "";
            if (w.on) {
                var bits = (w.detail || []).slice();
                if (w.active === false) bits.push(__("blocked"));
                if (w.last_seen) bits.push(__("last seen") + " " + w.last_seen);
                if (bits.length) extra = '<div class="cvs-sub" style="margin:0 0 4px 0">' + esc(bits.join(" · ")) + "</div>";
            } else if (w.note) {
                extra = '<div class="cvs-sub" style="margin:0 0 4px 0">' + esc(__("the last audit did not read this estate")) + "</div>";
            }
            return '<div class="cvs-line"><span class="k">' + esc(w.label) + "</span>" + p + "</div>" + extra;
        }).join("");
        var sub = d.audit.found
            ? __("Fleet Audit as of") + " " + age(d.audit)
            : __("This device is not in the Fleet Audit report");
        return '<div class="cvs-box"><div class="cvs-h">' + __("Where it is") + "</div>" + rows +
            '<div class="cvs-sub">' + sub + "</div></div>";
    }

    function wasl_box(d) {
        var w = d.wasl;
        var tone = w.state === "linked" ? "green"
            : (w.state === "registered_inactive" || w.state === "saved_not_registered") ? "orange"
                : (w.state === "not_listed" ? "red" : "grey");
        var body = '<div class="cvs-line">' + pill(w.label, tone) + "</div>";
        if (w.referencekey) body += '<div class="cvs-sub">' + __("Reference key") + ": " + esc(w.referencekey) + "</div>";
        if (w.changed_at) body += '<div class="cvs-sub">' + __("Last change") + ": " + esc(w.changed_at) + "</div>";
        body += '<div class="cvs-sub">' + (w.as_of ? __("Synced") + " " + age(w) : __("The WASL list has not been copied yet")) + "</div>";
        return '<div class="cvs-box"><div class="cvs-h">WASL</div>' + body + "</div>";
    }

    function sim_box(d) {
        var s = d.sim;
        if (!s.found) {
            return '<div class="cvs-box"><div class="cvs-h">' + __("SIM") + "</div>" +
                '<div class="cvs-line">' + pill(__("not on Lebara"), "grey") + "</div>" +
                '<div class="cvs-sub">' + esc(s.why || "") + "</div>" +
                (s.iccid ? '<div class="cvs-sub">' + __("SIM serial") + ": " + esc(s.iccid) + "</div>" : "") + "</div>";
        }
        var tone = s.status === "Active" ? "green" : (s.status === "Idle" ? "grey" : "orange");
        return '<div class="cvs-box"><div class="cvs-h">' + __("SIM") + " (Lebara)</div>" +
            '<div class="cvs-line">' + pill(s.status || "?", tone) + '<span class="k">' + esc(s.msisdn) + "</span></div>" +
            '<div class="cvs-sub">ICCID ' + esc(s.iccid) + "</div>" +
            (s.last_connection ? '<div class="cvs-sub">' + __("Last connection") + ": " + esc(s.last_connection) + "</div>" : "") +
            '<div class="cvs-sub">' + __("Synced") + " " + esc(s.as_of) + "</div></div>";
    }

    function device_box(d) {
        var s = d.sim;
        var p, note = "";
        if (!s.found) {
            p = pill(__("no SIM data"), "grey");
        } else if (s.imei_matches === "yes") {
            p = pill("✓ " + __("Matching IMEI"), "green");
        } else if (s.imei_matches === "no") {
            p = pill("✕ " + __("IMEI does not match"), "red");
        } else {
            p = pill(__("not reported"), "grey");
        }
        if (s.found && s.sim_imei) {
            note = '<div class="cvs-sub">' + __("SIM was last in") + ": " + esc(s.sim_imei) + "</div>" +
                '<div class="cvs-sub">' + __("This vehicle") + ": " + esc(d.imei) + "</div>";
        } else if (s.found) {
            note = '<div class="cvs-sub">' + __("Lebara has no device IMEI for this SIM yet") + "</div>";
        }
        return '<div class="cvs-box"><div class="cvs-h">' + __("SIM vs vehicle device") + "</div>" +
            '<div class="cvs-line">' + p + "</div>" + note + "</div>";
    }

    function html(d) {
        css();
        var issues = (d.issues || []).length
            ? '<div class="cvs-issues"><b>' + __("Needs a look") + "</b><ul>" +
                d.issues.map(function (t) { return "<li>" + esc(t) + "</li>"; }).join("") + "</ul></div>"
            : "";
        return '<div class="cvs-grid">' + where_box(d) + wasl_box(d) + sim_box(d) + device_box(d) + "</div>" + issues;
    }

    // Frappe attaches a dashboard section to `frm.dashboard.parent`, NOT to `frm.dashboard.wrapper`.
    // Looking in the wrapper found nothing, so every vehicle opened in the same form added another
    // section. The form object is reused when you move from one vehicle to the next, which is why the
    // old one stayed until a full refresh.
    function clear_section(frm) {
        try {
            var parent = frm.dashboard && frm.dashboard.parent;
            if (parent && parent.find) parent.find("." + SECTION).remove();
        } catch (e) { /* cosmetic */ }
    }

    frappe.ui.form.on("Customer Vehicle", {
        refresh: function (frm) {
            if (!SHOW_SYSTEMS_SECTION) return;
            clear_section(frm);
            if (frm.is_new()) return;
            var name = frm.doc.name;
            // two refreshes in a row, or a slow answer arriving after the user moved on: only the
            // newest request for the vehicle now on screen may draw
            frm._cvs_seq = (frm._cvs_seq || 0) + 1;
            var seq = frm._cvs_seq;
            frappe.call({
                method: METHOD,
                args: { vehicle: name },
                callback: function (r) {
                    var d = r && r.message;
                    if (!d || frm.doc.name !== name || frm._cvs_seq !== seq) return;
                    clear_section(frm);
                    frm.dashboard.add_section(html(d), __("Summary"), SECTION);
                    frm.dashboard.show();
                },
                error: function () { /* the section is a convenience; never break the form for it */ }
            });
        }
    });
})();
